// Exemplos individuais da especificação, com contratos numéricos verificados.
export const EXEMPLOS_COMPONENTES_UI = [{"id":"001","origem":"<nome_do_contador>","modelo":"contador <nome>","formula":"se @USUARIO.contador rancor >= 3 entao subtrair 2d8 em @ALVO.vida","explicacao":"Substitua o marcador pelo nome real do contador; neste caso, rancor acompanha a vingança acumulada. Com 3 ou mais pontos, a descarga causa 2d8; com 2, não dispara. O contador é o total combinado de todas as fontes.","legado":"se @USUARIO.rancor >= 3 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"002","origem":"<nome>__fonte__<id>","modelo":"contador <nome> fonte <id>","formula":"somar 1 em @USUARIO.contador brasas fonte reliquia_lunar","explicacao":"Esta forma acessa apenas a parcela do contador brasas fornecida pela fonte reliquia_lunar. O exemplo acrescenta uma carga nessa origem específica; outras fontes continuam separadas, permitindo aplicar tetos individuais por item, talento ou habilidade.","legado":"somar 1 em @USUARIO.brasas__fonte__reliquia_lunar","aliases":"nenhum listado"},{"id":"003","origem":"absorcao_armada","modelo":"absorcao pendente","formula":"se @USUARIO.absorcao pendente > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Depois de absorver um elemento, o próximo golpe pode descarregar 1d8 adicional. A chave vale 1 enquanto existir uma absorção elemental pendente e 0 quando não houver; associe a fórmula ao ataque que consome essa carga.","legado":"se @USUARIO.absorcao_armada > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"004","origem":"acao_bonus","modelo":"acao bonus","formula":"se @USUARIO.acao bonus > 0 entao subtrair 1 em @USUARIO.acao bonus, somar 1d8 em @USUARIO.vida","explicacao":"Uma poção rápida usa uma Ação Bônus e cura 1d8 PV. Se ainda houver 1 ação bônus nesta rodada, ela é gasta e a cura acontece; se o valor for 0, o personagem precisa esperar outra oportunidade. O recurso pode controlar outras ações curtas, não só poções.","legado":"se @USUARIO.acao_bonus > 0 entao subtrair 1 em @USUARIO.acao_bonus, somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"005","origem":"acao_disponivel","modelo":"acao comum disponivel","formula":"se @USUARIO.acao comum disponivel > 0 entao subtrair 1 em @USUARIO.ataques restantes, subtrair 1d10 em @ALVO.vida","explicacao":"Um golpe pesado exige que o personagem ainda tenha uma ação comum nesta rodada. Com ação disponível, consome uma e causa 1d10; sem ação, não ataca. A contagem de ataques e a disponibilidade de ação são consultadas no momento da execução.","legado":"se @USUARIO.acao_disponivel > 0 entao subtrair 1 em @USUARIO.ataques_restantes, subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"006","origem":"acerto","modelo":"acerto","formula":"se @USUARIO.acerto >= 6 entao subtrair 1d10 em @ALVO.vida","explicacao":"Uma técnica de precisão libera um dado de dano extra quando o bônus de Acerto personalizado chega a +6. Com +5, o efeito não ocorre; com +6 ou +8, aplica 1d10. Ataques normais continuam usando os cálculos próprios de cada tipo de arma.","legado":"se @USUARIO.acerto >= 6 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"007","origem":"ado_concedida","modelo":"oportunidade concedida","formula":"se @USUARIO.oportunidade concedida > 0 e @USUARIO.oportunidade consumida = 0 entao subtrair 2d6 + @USUARIO.treino em @ALVO.vida","explicacao":"Quando um inimigo sai do alcance e o Mestre concede uma AdO, a lança do personagem causa 2d6 mais Treinamento se a oportunidade ainda não foi gasta. Sem concessão ou depois de consumir a AdO, não há ataque. A fórmula une autorização da reação, estado de uso e dano de uma arma de haste.","legado":"se @USUARIO.ado_concedida > 0 e @USUARIO.ado_consumida = 0 entao subtrair 2d6 + @USUARIO.treino em @ALVO.vida","aliases":"nenhum listado"},{"id":"008","origem":"ado_consumida","modelo":"oportunidade consumida","formula":"se @USUARIO.oportunidade consumida = 0 entao subtrair 1 em @USUARIO.oportunidade restantes, subtrair 1d10 em @ALVO.vida","explicacao":"O contra-golpe exige que nenhuma oportunidade tenha sido consumida. Consome uma oportunidade restante e causa 1d10 ao alvo. A consulta consumida é somente leitura; configure o gatilho de saída de alcance e o limite de oportunidades na mesa.","legado":"se @USUARIO.ado_consumida = 0 entao somar 1 em @USUARIO.ado_consumida, subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"009","origem":"ado_max","modelo":"maximo oportunidade","formula":"definir @USUARIO.maximo oportunidade em @USUARIO.restante oportunidade","explicacao":"No início da rodada, copia o máximo de ataques de oportunidade para a contagem disponível. Se o personagem tem máximo 2, começa a rodada com 2 oportunidades; com máximo 1, recebe 1. Assim, a reposição acompanha talentos que aumentam o limite.","legado":"definir @USUARIO.ado_max em @USUARIO.ado_restantes","aliases":"nenhum listado"},{"id":"010","origem":"ado_modo","modelo":"modo oportunidade","formula":"se @USUARIO.modo oportunidade = 1 entao subtrair 1d8 + @USUARIO.treino em @ALVO.vida","explicacao":"Quando o modo da AdO está configurado como 1 (reação), esta fórmula libera o golpe de resposta com 1d8 mais Treinamento. Valores 2 e 3 representam modos de ação ou qualquer modo, então esta regra específica não os trata como reação.","legado":"se @USUARIO.ado_modo = 1 entao subtrair 1d8 + @USUARIO.treino em @ALVO.vida","aliases":"nenhum listado"},{"id":"011","origem":"ado_restantes","modelo":"restante oportunidade","formula":"se @USUARIO.restante oportunidade > 0 entao subtrair 1 em @USUARIO.restante oportunidade, subtrair 1d8 em @ALVO.vida","explicacao":"Quando um inimigo deixa o alcance, a reação só pode atacar se ainda houver uma AdO restante. Com 2 disponíveis, o gatilho gasta uma e causa 1d8; com 0, não executa. A chave representa o saldo atual de oportunidades, não o máximo da ficha.","legado":"se @USUARIO.ado_restantes > 0 entao subtrair 1 em @USUARIO.ado_restantes, subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"012","origem":"ado_restrita","modelo":"oportunidade restrita","formula":"se @USUARIO.oportunidade restrita > 0 e @CENA.distancia <= 1.5 entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma AdO limitada a um alvo só usa este efeito quando a restrição está ativa e a criatura autorizada está adjacente, a até 1,5 m. O marcador sinaliza que há um alvo específico definido pela configuração; a seleção desse alvo deve ser feita pelo gatilho.","legado":"se @USUARIO.ado_restrita > 0 e @CENA.distancia_m <= 1.5 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"013","origem":"agachado","modelo":"agachado","formula":"se @ALVO.agachado > 0 entao somar 2 em @ALVO.defesa","explicacao":"Um arqueiro agachado atrás de uma barricada recebe +2 de Defesa contra o próximo disparo. A fórmula aplica o bônus enquanto o marcador estiver ativo; ao se levantar, a Defesa volta ao valor normal.","legado":"se @ALVO.agachado > 0 entao somar 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"014","origem":"aliado_adjacente","modelo":"tem aliados adjacentes","formula":"se @USUARIO.tem aliados adjacentes > 0 entao somar 1d8 em @ALVO.vida","explicacao":"Uma técnica de transferência só pode curar um aliado quando pelo menos um companheiro está a até 1,5 m. Se não houver nenhum aliado adjacente, a ação não encontra um receptor próximo para os 1d8.","legado":"se @USUARIO.aliado_adjacente > 0 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"015","origem":"arma_grupo_<grupo>","modelo":"arma_principal grupo <grupo>","formula":"se @USUARIO.arma_principal grupo espada > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Troque <grupo> pelo grupo real da arma; espada é o identificador usado neste exemplo. Se a arma principal pertence ao grupo espada, o talento de lâminas acrescenta 2d6; uma arma de outro grupo não satisfaz a condição.","legado":"se @USUARIO.arma_grupo_espada > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"016","origem":"arma_margem_critico","modelo":"margem_critico arma_principal","formula":"se @USUARIO.margem_critico arma_principal <= 18 entao subtrair 2d8 em @ALVO.vida","explicacao":"Uma técnica de execução libera 2d8 extras para uma arma com margem crítica 18 ou melhor. Uma arma que critica em 18–20 ativa; outra que só critica em 20 não. O resultado do ataque continua sendo marcado como crítico pelo motor.","legado":"se @USUARIO.arma_margem_critico <= 18 entao subtrair 2d8 em @ALVO.vida","aliases":"arma_principal_crit_range"},{"id":"017","origem":"arma_principal_a_distancia","modelo":"arma_principal distancia","formula":"se @USUARIO.arma_principal distancia > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Um talento de atirador acrescenta 2d6 quando a arma principal é de ataque à distância. Com arco equipado como principal, ativa; com espada principal, não. arma_principal_eh_distancia consulta o mesmo estado.","legado":"se @USUARIO.arma_principal_a_distancia > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"arma_principal_eh_distancia"},{"id":"018","origem":"arma_principal_alcance","modelo":"alcance arma_principal","formula":"se @CENA.distancia <= @USUARIO.alcance arma_principal entao subtrair 1d8 em @ALVO.vida","explicacao":"Um golpe corpo a corpo só alcança o alvo se a distância da cena for menor ou igual ao alcance da arma principal. Uma arma com alcance 1,5 m atinge alguém adjacente; a 3 m, o ataque não passa nesta condição.","legado":"se @CENA.distancia_m <= @USUARIO.arma_principal_alcance entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"019","origem":"arma_principal_alcance_curto","modelo":"alcance arma_principal curto","formula":"se @CENA.distancia <= @USUARIO.alcance arma_principal curto entao subtrair 1d6 em @ALVO.vida","explicacao":"Uma adaga arremessada causa 1d6 se o alvo estiver dentro do alcance curto configurado na arma. Se o alcance curto for 6 m, um alvo a 5 m satisfaz a regra; a 7 m, não.","legado":"se @CENA.distancia_m <= @USUARIO.arma_principal_alcance_curto entao subtrair 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"020","origem":"arma_principal_alcance_longo","modelo":"alcance arma_principal longo","formula":"se @CENA.distancia <= @USUARIO.alcance arma_principal longo entao subtrair 1d8 em @ALVO.vida","explicacao":"Um arco longo alcança a distância registrada como alcance longo. Com limite 24 m, o alvo a 23 m ainda pode ser atingido; a 25 m fica fora. Em conjunto com a chave de alcance curto, o Mestre pode distinguir tiros sem penalidade de tiros no limite.","legado":"se @CENA.distancia_m <= @USUARIO.arma_principal_alcance_longo entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"021","origem":"arma_principal_corpo_a_corpo","modelo":"arma_principal corpo_a_corpo","formula":"se @USUARIO.arma_principal corpo_a_corpo > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma técnica de corte só adiciona 1d8 se a arma principal for corpo a corpo. Espada ou machado satisfazem o filtro; arco principal não. arma_principal_eh_cac é um alias da mesma propriedade.","legado":"se @USUARIO.arma_principal_corpo_a_corpo > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"arma_principal_eh_cac"},{"id":"022","origem":"arma_principal_crit_ampliado","modelo":"arma_principal critico_ampliado","formula":"se @USUARIO.arma_principal critico_ampliado > 0 entao subtrair 2d10 em @ALVO.vida","explicacao":"Quando a arma principal tem crítico ampliado (margem menor que 20), o golpe crítico recebe 2d10 extras nesta regra. Uma arma com margem 19 ativa a propriedade; uma arma que só critica em 20 não. Combine com o resultado crítico registrado pelo ataque.","legado":"se @USUARIO.arma_principal_crit_ampliado > 0 entao subtrair 2d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"023","origem":"arma_principal_fineza","modelo":"arma_principal fineza","formula":"se @USUARIO.arma_principal fineza > 0 entao subtrair 1d6 + @USUARIO.atributo des em @ALVO.vida","explicacao":"Uma adaga com Fineza pode usar Destreza no ataque, então o dano combina 1d6 com o atributo DES do usuário. Com Destreza 4 e dado 3, causa 7. Uma arma sem Fineza não usa este cálculo.","legado":"se @USUARIO.arma_principal_fineza > 0 entao subtrair 1d6 + @USUARIO.des em @ALVO.vida","aliases":"nenhum listado"},{"id":"024","origem":"arma_principal_leve","modelo":"arma_principal leve","formula":"se @USUARIO.arma_principal leve > 0 entao somar 1 em @USUARIO.ataques restantes","explicacao":"Uma lâmina leve permite uma sequência rápida: se a arma principal tem a propriedade Leve, o usuário recebe um ataque adicional. Uma arma sem essa propriedade não aumenta a contagem. O exemplo verifica a propriedade da arma, não o seu nome.","legado":"se @USUARIO.arma_principal_leve > 0 entao somar 1 em @USUARIO.ataques_restantes","aliases":"nenhum listado"},{"id":"025","origem":"arma_principal_pesada","modelo":"arma_principal pesada","formula":"se @USUARIO.arma_principal pesada > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um talento de armas pesadas acrescenta 2d8 quando a arma principal tem a propriedade Pesada. Uma marreta pesada ativa o efeito; uma espada leve não. A chave permite separar o benefício pela propriedade registrada no item.","legado":"se @USUARIO.arma_principal_pesada > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"026","origem":"arma_principal_versatil","modelo":"arma_principal versatil","formula":"se @USUARIO.arma_principal versatil > 0 entao subtrair 1d10 + @USUARIO.for em @ALVO.vida","explicacao":"Uma arma Versátil, como uma espada longa neste exemplo, pode ser usada com as duas mãos para causar 1d10 mais Força. Se a arma principal não tem a propriedade Versátil, esta fórmula não libera o modo de dano maior.","legado":"se @USUARIO.arma_principal_versatil > 0 entao subtrair 1d10 + @USUARIO.for em @ALVO.vida","aliases":"nenhum listado"},{"id":"027","origem":"astucia","modelo":"astucia","formula":"se @ALVO.astucia >= @CENA.dificuldade entao somar 1 em @ALVO.acerto","explicacao":"Ao resistir a uma finta complexa, o alvo usa Astúcia contra a CD da cena. Astúcia 14 contra CD 13 permite reconhecer o truque e recebe +1 de Acerto na resposta; 12 não identifica a manobra.","legado":"se @ALVO.astucia >= @CENA.dificuldade entao somar 1 em @ALVO.acerto","aliases":"nenhum listado"},{"id":"028","origem":"ataques_neste_turno","modelo":"ataques neste turno","formula":"se @USUARIO.ataques neste turno >= 2 entao somar 1d8 em @ALVO.vida temporaria","explicacao":"Após dois ataques no turno, uma postura de duelista cria 1d8 PV temporários para se proteger da resposta inimiga. Com zero ou um ataque realizado, o benefício ainda não ativa; o segundo golpe completa a sequência.","legado":"se @USUARIO.ataques_neste_turno >= 2 entao somar 1d8 em @ALVO.vida_temp","aliases":"nenhum listado"},{"id":"029","origem":"ataques_no_turno","modelo":"maximo ataques turno","formula":"se @USUARIO.maximo ataques turno >= 2 entao subtrair 1d6 em @ALVO.vida","explicacao":"Uma técnica de sequência só habilita o golpe adicional se a ficha permite pelo menos dois ataques neste turno. Com limite 1, não há segundo golpe; com limite 2 ou 3, o efeito aplica 1d6 ao alvo. A chave consulta a capacidade total do turno.","legado":"se @USUARIO.ataques_no_turno >= 2 entao subtrair 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"030","origem":"ataques_restantes","modelo":"ataques restantes","formula":"se @USUARIO.ataques restantes > 0 entao subtrair 1 em @USUARIO.ataques restantes, subtrair 1d8 + @USUARIO.for em @ALVO.vida","explicacao":"Este ataque só ocorre enquanto houver uma ação de ataque disponível. Com 1 restante, consome essa ação e aplica 1d8 + Força; com 0, não consome nada. acoes_restantes é um alias aceito para a mesma contagem.","legado":"se @USUARIO.ataques_restantes > 0 entao subtrair 1 em @USUARIO.ataques_restantes, subtrair 1d8 + @USUARIO.for em @ALVO.vida","aliases":"acao_restante, acoes_restantes"},{"id":"031","origem":"atencao","modelo":"atencao","formula":"se @USUARIO.atencao >= @ALVO.pericia furtividade entao somar 2 em @USUARIO.acerto","explicacao":"Um vigia percebe o inimigo escondido quando sua Atenção passiva iguala ou supera a Furtividade dele. Com Atenção 15 contra Furtividade 14, revela a posição e recebe +2 de Acerto no primeiro contra-ataque; contra Furtividade 16, a condição falha.","legado":"se @USUARIO.atencao >= @ALVO.pericia_furtividade entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"032","origem":"atencao_bonus","modelo":"bonus atencao","formula":"somar @USUARIO.bonus atencao em @USUARIO.atencao","explicacao":"Ao recalcular a Atenção passiva, soma o bônus vindo dos talentos ao valor-base. Se a ficha concede +2, Atenção 13 passa a 15; se não houver bônus, o total permanece 13. A chave mantém o ajuste separado do atributo principal.","legado":"somar @USUARIO.atencao_bonus em @USUARIO.atencao","aliases":"nenhum listado"},{"id":"033","origem":"atras_de_cobertura","modelo":"cobertura presente","formula":"se @ALVO.cobertura presente > 0 entao somar 2 em @ALVO.defesa","explicacao":"Um inimigo atrás de cobertura recebe +2 de Defesa contra o disparo. O bônus vale tanto para meia cobertura quanto para proteção superior, conforme a chave; sem cobertura, não altera a Defesa.","legado":"se @ALVO.atras_de_cobertura > 0 entao somar 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"034","origem":"au","modelo":"aptidao au","formula":"subtrair 1d8 + @USUARIO.aptidao au em @ALVO.vida","explicacao":"Uma técnica da família AU usa o valor de aptidão Aura do usuário para ampliar o impacto. Com AU 3 e resultado 5 no d8, causa 8 de dano. Se o valor de aptidão aumentar, a fórmula escala sem trocar a chave nem a habilidade.","legado":"subtrair 1d8 + @USUARIO.au em @ALVO.vida","aliases":"nenhum listado"},{"id":"035","origem":"au_concentrada","modelo":"aura concentrada","formula":"se @USUARIO.aura concentrada > 0 entao somar @USUARIO.aura concentrada * 2 em @ALVO.vida temporaria","explicacao":"Uma aura concentra 3 AU no aliado e concede 6 PV temporários: cada ponto concentrado vale 2. Com 0 AU, não há escudo; com 3, soma 6 ao alvo. O valor consultado é o AU armazenado na aura concentrada.","legado":"se @USUARIO.au_concentrada > 0 entao somar @USUARIO.au_concentrada * 2 em @ALVO.vida_temp","aliases":"nenhum listado"},{"id":"036","origem":"aura_bonus_agarrar","modelo":"bonus aura agarrar","formula":"somar @USUARIO.bonus aura agarrar em @USUARIO.pericia atletismo","explicacao":"Uma aura de contenção soma seu bônus ao teste de Atletismo usado para agarrar. Se concede +2, Atletismo 5 passa a 7 na manobra; a chave pode refletir a potência da aura sem alterar o atributo ou a perícia da ficha.","legado":"somar @USUARIO.aura_bonus_agarrar em @USUARIO.pericia_atletismo","aliases":"aura_agarrar_bonus"},{"id":"037","origem":"aura_bonus_defesa","modelo":"bonus aura defesa","formula":"somar @USUARIO.bonus aura defesa em @USUARIO.defesa","explicacao":"Uma aura protetora acrescenta à Defesa o bônus que ela concede aos aliados próximos. Se o bônus de aura for +2, a Defesa 15 passa a 17 enquanto o efeito estiver ativo. A fórmula lê o valor da aura em vez de fixar o bônus na habilidade.","legado":"somar @USUARIO.aura_bonus_defesa em @USUARIO.defesa","aliases":"aura_ca_bonus"},{"id":"038","origem":"aura_bonus_furtividade","modelo":"bonus aura furtividade","formula":"somar @USUARIO.bonus aura furtividade em @USUARIO.pericia furtividade","explicacao":"Enquanto estiver dentro da aura de ocultação, o personagem soma o bônus dela à própria Furtividade. Com +3 de aura, Furtividade 6 passa a 9; fora do alcance ou sem aura ativa, use apenas o valor normal.","legado":"somar @USUARIO.aura_bonus_furtividade em @USUARIO.pericia_furtividade","aliases":"aura_furtividade_bonus"},{"id":"039","origem":"aura_reducao_dano_fisico","modelo":"reducao dano fisico aura","formula":"subtrair max(1, 2d8 - @ALVO.reducao dano fisico aura) em @ALVO.vida","explicacao":"Uma aura reduz o dano físico recebido pelo alvo antes de aplicar os PV perdidos. Contra 2d8 que somam 9, uma RD de aura 3 deixa 6; caso a redução cubra tudo, ainda se aplica 1 pelo mínimo escolhido no exemplo. A mitigação vale para ataques físicos.","legado":"subtrair max(1, 2d8 - @ALVO.aura_reducao_dano_fisico) em @ALVO.vida","aliases":"aura_rd_fisica"},{"id":"040","origem":"bar","modelo":"aptidao bar","formula":"somar @USUARIO.aptidao bar * 3 em @USUARIO.vida temporaria","explicacao":"Cada ponto de BAR, a aptidão Barreira, cria 3 pontos de vida temporários. BAR 2 concede 6; BAR 4 concede 12. O efeito entra na camada temporária de proteção, sem aumentar a Vida Máxima nem curar os PV atuais.","legado":"somar @USUARIO.bar * 3 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"041","origem":"bloqueio_total","modelo":"bloqueio total","formula":"somar 1 em @USUARIO.bloqueio total","explicacao":"Uma postura defensiva ativa o bloqueio total ao definir a flag como 1. Quando o personagem receber o próximo dano em Vida Atual, o motor absorve esse dano e zera a flag conforme a regra descrita para a chave. O efeito não cria pontos de vida nem acumula bloqueios indefinidamente.","legado":"somar 1 em @USUARIO.bloqueio_total","aliases":"nenhum listado"},{"id":"042","origem":"bonus_acao_disponivel","modelo":"acao bonus disponivel","formula":"se @USUARIO.acao bonus disponivel > 0 entao somar 1d8 em @USUARIO.vida","explicacao":"Uma poção rápida pode ser bebida se ainda houver Ação Bônus: a fórmula cura 1d8 PV. Se a ação bônus já foi gasta, não acontece; usar esse marcador evita consumir a ação comum em uma interação simples.","legado":"se @USUARIO.bonus_acao_disponivel > 0 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"043","origem":"bonus_ataque_magia","modelo":"bonus ataque magia","formula":"definir 1d20 + @USUARIO.bonus ataque magia em @USUARIO.contador resultado_magico","explicacao":"Registra uma rolagem de ataque mágico no contador resultado_magico. Com bônus +5 e dado 12, grava 17. Compare esse resultado com a Defesa do alvo no fluxo do feitiço; gravar o resultado não aplica dano automaticamente.","legado":"1d20 + @USUARIO.bonus_ataque_magia","aliases":"spell_attack_bonus"},{"id":"044","origem":"bonus_defesa_cobertura","modelo":"bonus cobertura","formula":"se @ALVO.bonus cobertura < 999 entao somar @ALVO.bonus cobertura em @ALVO.defesa","explicacao":"Aplica o bônus numérico de cobertura: 0 sem cobertura, +2 em meia e +5 em três quartos. O valor 999 representa cobertura total e é um marcador de imunidade; a condição impede somá-lo como se fossem 999 pontos normais de Defesa.","legado":"se @ALVO.bonus_defesa_cobertura < 999 entao somar @ALVO.bonus_defesa_cobertura em @ALVO.defesa","aliases":"nenhum listado"},{"id":"045","origem":"bonus_movimento","modelo":"bonus movimento","formula":"somar @USUARIO.bonus movimento em @USUARIO.contador metros_taticos","explicacao":"Uma habilidade de mobilidade acrescenta ao contador metros_taticos os metros extras concedidos por talentos. Se o bônus for 3 m, acrescenta 3 ao saldo de metros_taticos; se não houver bônus, não acrescenta nada. A chave evita fixar a velocidade no efeito. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"somar @USUARIO.bonus_movimento em @USUARIO.movimento_restante","aliases":"movimento_bonus_metros"},{"id":"046","origem":"bonus_slots_liberacao","modelo":"bonus slots liberacao","formula":"se @USUARIO.bonus slots liberacao >= 2 entao subtrair 2d8 em @ALVO.vida","explicacao":"Uma técnica de Liberação aprimorada só libera seu impacto de 2d8 quando os talentos concedem ao menos dois espaços universais extras. Com bônus 1, a condição falha; com bônus 2 ou maior, a técnica fica disponível. O exemplo usa a chave como requisito sem inventar um recurso de slots separado.","legado":"se @USUARIO.bonus_slots_liberacao >= 2 entao subtrair 2d8 em @ALVO.vida","aliases":"slots_liberacao_bonus"},{"id":"047","origem":"bonus_tr_defesa_reduzida","modelo":"bonus resistencia defesa_reduzida","formula":"somar @USUARIO.bonus resistencia defesa_reduzida em @USUARIO.reflexos","explicacao":"Quando uma condição reduz a Defesa, esta regra acrescenta ao TR de Reflexos o bônus específico configurado para essa situação. Se o bônus for +2 e Reflexos valer 5, o teste usa 7; sem a condição de Defesa reduzida, não inclua esse modificador.","legado":"somar @USUARIO.bonus_tr_defesa_reduzida em @USUARIO.reflexos","aliases":"tr_vs_debuff_defesa_bonus"},{"id":"048","origem":"carteiras_compartilhadas","modelo":"quantidade carteiras compartilhadas","formula":"se @USUARIO.quantidade carteiras compartilhadas > 0 entao somar 1d6 em @USUARIO.pe","explicacao":"Uma carteira compartilhada com a companhia permite recuperar 1d6 PE ao requisitar energia do fundo comum. Se não houver carteira compartilhada, o recurso não é liberado. Carteiras exclusivamente pessoais não contam para esta checagem.","legado":"se @USUARIO.carteiras_compartilhadas > 0 entao somar 1d6 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"049","origem":"carteiras_qtd","modelo":"quantidade carteiras","formula":"se @USUARIO.quantidade carteiras >= 3 entao somar 2 em @USUARIO.acerto","explicacao":"Um personagem que participa de três ou mais carteiras tem acesso a suprimentos em várias bases e recebe +2 de Acerto nesta regra de campanha. Com duas carteiras, não atinge o requisito; com três, ativa o benefício.","legado":"se @USUARIO.carteiras_qtd >= 3 entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"050","origem":"categoria","modelo":"categoria","formula":"se @ALVO.categoria = 3 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma habilidade de caçador causa 1d8 adicional apenas contra inimigos, identificados pelo valor 3. Jogadores (1) e NPCs (2) não ativam o efeito. Isso mostra como adaptar uma fórmula à categoria da entidade sem depender do nome do personagem.","legado":"se @ALVO.categoria = 3 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"051","origem":"CENA.ano","modelo":"ano","formula":"se @CENA.ano >= 1000 entao somar 2 em @USUARIO.pe maximo","explicacao":"Uma relíquia desperta no milésimo ano da cronologia e aumenta o PE máximo em 2. No ano 999 continua inativa; no ano 1000 e nos seguintes, aplica-se. O valor pertence ao calendário do jogo, não ao ano do computador.","legado":"se @CENA.ano >= 1000 entao somar 2 em @USUARIO.pe_max","aliases":"nenhum listado"},{"id":"052","origem":"CENA.consumido","modelo":"consumido","formula":"subtrair (@CENA.consumido)d8 em @ALVO.vida","explicacao":"Se a etapa anterior consumiu 3 unidades, @CENA.consumido vale 3 e esta fórmula rola 3d8 de dano. Com 1 unidade, rola 1d8. Use após CONSUMIR_CONTADOR quando o efeito posterior deve escalar com a quantidade realmente gasta, não com o total que havia.","legado":"subtrair (@CENA.consumido)d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"053","origem":"CENA.dano","modelo":"dano evento","formula":"se @CENA.dano evento >= 10 entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Uma reação cria escudo de 1d8 quando o dano do evento atual foi de pelo menos 10. Um golpe de 12 aciona a proteção; um de 9 não. Esta chave lê o valor informado pelo evento de dano e pode filtrar respostas a golpes fortes.","legado":"se @CENA.dano >= 10 entao somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"054","origem":"CENA.dia","modelo":"dia","formula":"se @CENA.dia = 15 entao somar 1d8 em @USUARIO.vida","explicacao":"No dia 15 de cada mês in-game, um santuário cura 1d8 PV dos personagens que descansarem ali. No dia 14 ou 16, o evento não se aplica. O campo é o dia do mês, então a regra se repete em cada mês.","legado":"se @CENA.dia = 15 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"055","origem":"CENA.diferenca_altura","modelo":"diferenca altura","formula":"se @CENA.diferenca altura >= 3 entao subtrair 1d10 em @ALVO.vida","explicacao":"Um ataque ascendente recebe 1d10 extra quando o alvo está pelo menos 3 m acima do usuário. A diferença é alvo menos usuário: +3 m indica que está acima; valor negativo indica que está abaixo e não ativa este exemplo.","legado":"se @CENA.diferenca_altura >= 3 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"056","origem":"CENA.dificuldade","modelo":"dificuldade","formula":"se @USUARIO.pericia ocultismo >= @CENA.dificuldade entao somar 1 em @USUARIO.sorte","explicacao":"Ao investigar um selo, Ocultismo 15 contra a CD 14 definida pelo Mestre revela uma pista e concede 1 uso de Sorte; 13 contra CD 14 falha. Mudar a dificuldade na cena ajusta a mesma fórmula a grupos mais ou menos experientes.","legado":"se @USUARIO.pericia_ocultismo >= @CENA.dificuldade entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"057","origem":"CENA.distancia_grade","modelo":"distancia grade","formula":"se @CENA.distancia grade <= 4.5 entao subtrair 2d6 em @ALVO.vida","explicacao":"Com casas de 1,5 m, um golpe de lança cobre até três casas, ou 4,5 m pela distância da grade. O alvo a três casas satisfaz o alcance; a quatro casas (6 m) não. Esta leitura segue a geometria configurada no mapa.","legado":"se @CENA.distancia_grade <= 4.5 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"058","origem":"CENA.distancia_m","modelo":"distancia <quantidade em metros>","formula":"se @CENA.distancia <= 3 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma lança alcança um alvo que esteja a até 3 m. A 2 m, a condição libera o dano de 1d8; a 4 m, não. A distância precisa ser fornecida no contexto da cena quando a fórmula é avaliada.","legado":"se @CENA.distancia_m <= 3 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"059","origem":"CENA.distancia_plana","modelo":"distancia plana","formula":"se @CENA.distancia plana <= 6 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um arco curto alcança até 6 m no plano horizontal. O disparo recebe 1d8 adicional contra uma peça a 5 m, mesmo que esteja em um nível de altura diferente; a diferença vertical é calculada separadamente por outra chave.","legado":"se @CENA.distancia_plana <= 6 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"060","origem":"CENA.eh_amanhecer","modelo":"periodo amanhecer","formula":"se @CENA.periodo amanhecer > 0 entao somar 1d8 em @USUARIO.vida","explicacao":"Uma bênção de alvorada recupera 1d8 PV quando o relógio marca amanhecer, entre 05h e 07h. Às 06h ativa; às 08h já não. Use o marcador para efeitos limitados à transição da noite para o dia.","legado":"se @CENA.eh_amanhecer > 0 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"061","origem":"CENA.eh_anoitecer","modelo":"periodo anoitecer","formula":"se @CENA.periodo anoitecer > 0 entao somar 1d6 em @USUARIO.vida temporaria","explicacao":"Quando começa o anoitecer, entre 18h e 20h, o personagem recebe 1d6 PV temporários da aura crepuscular. Às 19h ativa; às 21h não. A condição permite criar efeitos de passagem de período sem fixar uma hora própria.","legado":"se @CENA.eh_anoitecer > 0 entao somar 1d6 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"062","origem":"CENA.eh_dia","modelo":"periodo dia","formula":"se @CENA.periodo dia > 0 entao somar 2 em @USUARIO.pericia percepcao","explicacao":"Uma patrulha recebe +2 em Percepção durante o período diurno, definido pelo relógio como 07h–18h. Às 10h ativa; de madrugada não. O marcador booleano poupa repetir a faixa de horas na fórmula.","legado":"se @CENA.eh_dia > 0 entao somar 2 em @USUARIO.pericia_percepcao","aliases":"nenhum listado"},{"id":"063","origem":"CENA.eh_noite","modelo":"periodo noite","formula":"se @CENA.periodo noite > 0 entao somar 2 em @USUARIO.pericia furtividade","explicacao":"Uma capa de sombras dá +2 em Furtividade durante a noite, entre 20h e 05h conforme o relógio do jogo. Às 22h o marcador vale 1; no meio da tarde vale 0. A regra acompanha a faixa definida pelo sistema.","legado":"se @CENA.eh_noite > 0 entao somar 2 em @USUARIO.pericia_furtividade","aliases":"nenhum listado"},{"id":"064","origem":"CENA.eventos_hoje","modelo":"quantidade eventos hoje","formula":"se @CENA.quantidade eventos hoje >= 2 entao somar 1d8 em @USUARIO.vida","explicacao":"Em um festival com dois ou mais eventos no calendário de hoje, os participantes recuperam 1d8 PV pela animação da cidade. Um dia com zero ou um evento não satisfaz o requisito. A chave conta eventos agendados para a data atual.","legado":"se @CENA.eventos_hoje >= 2 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"065","origem":"CENA.hora","modelo":"hora","formula":"se @CENA.hora >= 22 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um guarda aplica a punição de toque de recolher a partir das 22h: qualquer intruso que ainda estiver na rua recebe 1d8 de dano nesta regra. Às 21h não ocorre. A hora usa a escala de 0 a 23 do relógio da cena.","legado":"se @CENA.hora >= 22 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"066","origem":"CENA.mes","modelo":"mes","formula":"se @CENA.mes = 12 entao subtrair 2 em @USUARIO.contador metros_taticos","explicacao":"Durante o mês 12, uma nevasca reduz em 2 m o saldo de metros_taticos na região. Em outros meses, essa penalidade sazonal não entra. O mês é numérico (1–12), permitindo adaptar clima e calendário da campanha. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @CENA.mes = 12 entao subtrair 2 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"067","origem":"CENA.minuto","modelo":"minuto","formula":"se @CENA.minuto >= 30 entao somar 1 em @USUARIO.pe","explicacao":"Uma ampulheta libera 1 PE depois que o minuto atual chega a 30. Às 14:29, o marco ainda não foi alcançado; às 14:30, a fórmula passa a satisfazê-lo. Use o minuto (0–59) para eventos dentro da hora.","legado":"se @CENA.minuto >= 30 entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"068","origem":"CENA.multiplicador_tempo","modelo":"velocidade relogio","formula":"somar ceil(10 * @CENA.velocidade relogio) em @USUARIO.reserva pe","explicacao":"Um ritual acumula energia proporcional à velocidade do relógio: com multiplicador 1, acrescenta 10 à reserva; em velocidade 2, acrescenta 20. ceil arredonda para cima caso o ritmo produza uma fração.","legado":"somar ceil(10 * @CENA.multiplicador_tempo) em @USUARIO.reserva_pe","aliases":"nenhum listado"},{"id":"069","origem":"CENA.no_mapa","modelo":"mapa ambos","formula":"se @CENA.mapa ambos > 0 e @CENA.distancia <= 3 entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma lança de guarda só ameaça o alvo se ambos tiverem peças no mapa e estiverem a até 3 m. Com as duas peças a 2 m, aplica 2d6; sem uma peça posicionada, não presume distância nem dispara. A fórmula combina a disponibilidade espacial com o alcance.","legado":"se @CENA.no_mapa > 0 e @CENA.distancia_m <= 3 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"070","origem":"CENA.outro_aliado","modelo":"outro aliado","formula":"se @CENA.outro aliado = 1 entao somar 1d8 em @ALVO.vida","explicacao":"Uma reação de apoio restaura 1d8 PV quando o outro participante registrado no evento é aliado. Se um aliado causou o evento, ativa; se a outra criatura for inimiga ou não houver participante aliado, não cura.","legado":"se @CENA.outro_aliado = 1 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"071","origem":"CENA.outro_e_voce","modelo":"outro e voce","formula":"se @CENA.outro e voce = 1 entao somar 1d6 em @USUARIO.vida temporaria","explicacao":"Uma barreira pessoal se ativa quando o outro envolvido no evento é o próprio usuário, concedendo 1d6 PV temporários. O marcador impede que a mesma reação seja gasta em acontecimentos que envolvam apenas outras criaturas.","legado":"se @CENA.outro_e_voce = 1 entao somar 1d6 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"072","origem":"CENA.outro_inimigo","modelo":"outro inimigo","formula":"se @CENA.outro inimigo = 1 entao somar 2 em @USUARIO.defesa","explicacao":"Ao observar um evento com outra criatura inimiga envolvida, o usuário ganha +2 de Defesa para se proteger da ameaça. Contra um evento sem inimigo associado, a condição vale 0 e o bônus não entra. Use em reações que filtram quem participou do evento.","legado":"se @CENA.outro_inimigo = 1 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"073","origem":"CENA.qtd_aliados","modelo":"quantidade aliados","formula":"se @CENA.quantidade aliados >= 3 entao somar 1d8 em @ALVO.vida","explicacao":"Uma cura em cadeia salta para um aliado quando a cena tem pelo menos três tokens de PLAYER. Com dois aliados em campo não ativa; com três ou mais, restaura 1d8 no alvo escolhido.","legado":"se @CENA.qtd_aliados >= 3 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"074","origem":"CENA.qtd_inimigos","modelo":"quantidade inimigos","formula":"subtrair @CENA.quantidade inimigos * 2 em @ALVO.vida","explicacao":"Uma onda de choque causa 2 pontos por inimigo presente na cena. Com quatro tokens INIMIGO, cada alvo afetado recebe 8 de dano; com um, recebe 2. O total conta tokens de inimigos visíveis, não aliados próximos.","legado":"subtrair @CENA.qtd_inimigos * 2 em @ALVO.vida","aliases":"nenhum listado"},{"id":"075","origem":"CENA.qtd_tokens","modelo":"quantidade tokens","formula":"se @CENA.quantidade tokens >= 8 entao somar 2 em @USUARIO.defesa","explicacao":"Uma formação defensiva concede +2 de Defesa quando há oito ou mais tokens visíveis na cena. Com sete criaturas, o grupo ainda não fecha o círculo; ao chegar a oito, a proteção coletiva ativa.","legado":"se @CENA.qtd_tokens >= 8 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"076","origem":"CENA.relogio_ativo","modelo":"relogio ativo","formula":"se @CENA.relogio ativo > 0 entao subtrair 1 em @USUARIO.pe","explicacao":"Manter uma barreira temporal ativa drena 1 PE em cada pulso enquanto o relógio do jogo está rodando. Durante uma pausa do Mestre, a condição não cobra energia. Vincule a linha ao pulso de tempo configurado para a barreira, de modo que a drenagem não se repita em cada ação.","legado":"se @CENA.relogio_ativo > 0 entao subtrair 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"077","origem":"CENA.rodada","modelo":"rodada","formula":"quando @CENA.rodada = 1 -> somar 2 em @USUARIO.acerto","explicacao":"Uma postura de abertura concede +2 de Acerto durante a primeira rodada do combate. O gatilho é verdadeiro quando a cena marca a rodada como 1; na rodada 2 ele já não dispara. É útil para emboscadas ou efeitos que só duram no início do confronto.","legado":"quando @CENA.rodada = 1 -> somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"078","origem":"CENA.rodadas_em_combate","modelo":"rodadas_em_combate","formula":"quando @CENA.rodadas_em_combate >= 4 -> subtrair 1d8 em @ALVO.vida","explicacao":"Um veneno tardio começa a causar 1d8 a partir da quarta rodada de combate. Antes disso, o gatilho ainda não atingiu o limite; na rodada 4 e nas seguintes, pode disparar. Fora de combate a chave vale 0, então não confunde tempo narrativo com rodadas de luta.","legado":"quando @CENA.rodadas_em_combate >= 4 -> subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"079","origem":"CENA.segundo","modelo":"segundo","formula":"se @CENA.segundo = 0 entao somar 1 em @USUARIO.reserva pe","explicacao":"Um mecanismo de relógio armazena 1 PE sempre que o evento é avaliado no começo exato do segundo, quando o campo vale 0. Nos segundos 1 a 59, não acumula. Combine com um gatilho de avanço do relógio para evitar repetir dentro do mesmo instante.","legado":"se @CENA.segundo = 0 entao somar 1 em @USUARIO.reserva_pe","aliases":"nenhum listado"},{"id":"080","origem":"CENA.sujeito_aliado","modelo":"sujeito aliado","formula":"se @CENA.sujeito aliado = 1 entao somar 2d8 em @ALVO.vida","explicacao":"Uma aura de socorro restaura 2d8 PV apenas quando a criatura observada é aliada. O marcador 1 libera a cura; se o sujeito for inimigo ou não estiver marcado como aliado, a fórmula não o cura.","legado":"se @CENA.sujeito_aliado = 1 entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"081","origem":"CENA.terreno","modelo":"terreno","formula":"se @CENA.terreno < 2 entao subtrair 1.5 em @USUARIO.contador metros_taticos","explicacao":"Uma criatura só atravessa a casa se o terreno não estiver marcado como intransponível (valor 2). Terreno normal (0) e difícil (1) permitem avançar 1,5 m; com valor 2, a condição bloqueia o movimento. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @CENA.terreno < 2 entao subtrair 1.5 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"082","origem":"CENA.timestamp_segundos","modelo":"segundos dia","formula":"se @CENA.segundos dia >= 43200 entao somar 1 em @USUARIO.sorte","explicacao":"Uma bênção diária fica disponível depois de 43.200 segundos desde meia-noite, isto é, ao meio-dia. Antes desse instante, não concede Sorte; ao atingir 12:00, concede 1 uso. O timestamp permite comparar períodos longos em uma unidade única.","legado":"se @CENA.timestamp_segundos >= 43200 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"083","origem":"CENA.token_x","modelo":"posicao x","formula":"se @CENA.posicao x >= 12 entao somar 2 em @USUARIO.defesa","explicacao":"Uma runa protege a faixa leste do mapa: quando a coordenada X do token chega a 12 m ou mais, concede +2 de Defesa. Em X=11,5 m ainda não ativa. As coordenadas estão em metros, não em número de casas.","legado":"se @CENA.token_x >= 12 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"084","origem":"CENA.token_y","modelo":"posicao y","formula":"se @CENA.posicao y <= 3 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma fileira de espinhos cobre a borda sul, até Y=3 m. Um token em Y=2 sofre 1d8 quando a regra da armadilha dispara; em Y=4 está fora da faixa. A chave representa a coordenada vertical do mapa.","legado":"se @CENA.token_y <= 3 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"085","origem":"CENA.turno_indice","modelo":"indice turno","formula":"se @CENA.indice turno = 0 entao somar 2 em @USUARIO.acerto","explicacao":"A ficha que ocupa o primeiro lugar na ordem de iniciativa tem índice 0; neste exemplo, ganha +2 de Acerto na abertura do turno. Índice 1 ou maior não recebe o bônus, e -1 indica que não existe turno válido.","legado":"se @CENA.turno_indice = 0 entao somar 2 em @USUARIO.acerto","aliases":"CENA.turno_de"},{"id":"086","origem":"cl","modelo":"aptidao cl","formula":"se @USUARIO.aptidao cl >= 2 entao somar 2 em @USUARIO.pericia feiticaria","explicacao":"Uma prática de Clareza concede +2 em Feitiçaria quando o usuário tem CL 2 ou maior. CL 1 não libera o bônus; CL 2 e CL 3 liberam. A chave deixa que o requisito da aptidão controle efeitos diferentes.","legado":"se @USUARIO.cl >= 2 entao somar 2 em @USUARIO.pericia_feiticaria","aliases":"nenhum listado"},{"id":"087","origem":"cobertura_meia","modelo":"cobertura meia","formula":"se @ALVO.cobertura meia > 0 entao somar 2 em @ALVO.defesa","explicacao":"Uma barricada baixa concede +2 de Defesa ao alvo atrás de meia cobertura. Sem esse nível de proteção, o bônus não se aplica; cobertura de três quartos usa a chave própria e concede o valor correspondente.","legado":"se @ALVO.cobertura_meia > 0 entao somar 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"088","origem":"cobertura_total","modelo":"cobertura total","formula":"se @ALVO.cobertura total = 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"O disparo direto só atinge o alvo se ele não estiver protegido por cobertura total. Com marcador 0, aplica 2d8; com marcador 1, a fórmula bloqueia o dano direto. imune_por_cobertura é um alias aceito para esse marcador.","legado":"se @ALVO.cobertura_total = 0 entao subtrair 2d8 em @ALVO.vida","aliases":"imune_por_cobertura"},{"id":"089","origem":"cobertura_tres_quartos","modelo":"cobertura tres_quartos","formula":"se @ALVO.cobertura tres_quartos > 0 entao somar 5 em @ALVO.defesa","explicacao":"Uma parede que protege três quartos do corpo concede +5 de Defesa ao alvo contra ataques diretos. Se houver apenas meia cobertura, esta chave fica em 0 e não soma os cinco pontos.","legado":"se @ALVO.cobertura_tres_quartos > 0 entao somar 5 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"090","origem":"con","modelo":"atributo con","formula":"somar @USUARIO.atributo con * 2 em @USUARIO.vida max","explicacao":"Uma passiva de vigor pode aumentar a Vida Máxima em 2 pontos por ponto de Constituição. Com Constituição 3, o bônus acrescenta 6 à capacidade máxima. Como o destino é vida_max, isso altera o limite da ficha, não cura automaticamente a vida atual.","legado":"somar @USUARIO.con * 2 em @USUARIO.vida_max","aliases":"constituicao"},{"id":"091","origem":"concentracao_maxima","modelo":"maximo concentracao","formula":"se @USUARIO.maximo concentracao >= 2 entao somar 1 em @USUARIO.pe","explicacao":"Uma passiva de foco recupera 1 PE se o limite de espaços de concentração do personagem for pelo menos 2. Com limite 1, a condição falha; com limite 2 ou 3, a recuperação ocorre. A chave consulta capacidade máxima, não quantos espaços estão ocupados.","legado":"se @USUARIO.concentracao_maxima >= 2 entao somar 1 em @USUARIO.pe","aliases":"max_concentracao"},{"id":"092","origem":"concentrando","modelo":"concentrando","formula":"se @USUARIO.concentrando > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Enquanto mantém um feitiço sustentado, o conjurador recebe +2 de Defesa por manter uma postura de concentração. Quando não está concentrando, o bônus não se aplica. A condição pode controlar custos, proteção ou penalidades ligadas a manter um efeito ativo.","legado":"se @USUARIO.concentrando > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"093","origem":"condicao_rodadas_desde_<id>","modelo":"idade condicao <id>","formula":"se @ALVO.idade condicao envenenado >= 3 entao subtrair 2d8 em @ALVO.vida","explicacao":"Substitua <id> por envenenado para consultar há quantas rodadas essa condição está ativa. A partir da terceira rodada completa, uma toxina tardia causa 2d8; antes disso, ainda não. Valor -1 significa que a condição está ausente ou sem idade conhecida.","legado":"se @ALVO.condicao_rodadas_desde_envenenado >= 3 entao subtrair 2d8 em @ALVO.vida","aliases":"condicao_idade_rodadas_<id>"},{"id":"094","origem":"condicao_rodadas_restantes_<id>","modelo":"restante condicao <id>","formula":"se @ALVO.restante condicao amedrontado <= 1 entao remover amedrontado","explicacao":"Para a condição Amedrontado, esta limpeza remove o efeito quando resta uma rodada ou menos. Com 2 rodadas restantes, ele continua; com 1, termina. O valor 999 indica duração indefinida, então não é removido por esse limite.","legado":"se @ALVO.condicao_rodadas_restantes_amedrontado <= 1 entao remover amedrontado","aliases":"condicao_rodadas_<id>"},{"id":"095","origem":"condicao_tem_idade_<id>","modelo":"condicao <id> idade_conhecida","formula":"se @ALVO.condicao amedrontado idade_conhecida > 0 entao somar 1d6 em @USUARIO.vida","explicacao":"Use amedrontado no lugar de <id> para verificar se a idade da condição foi registrada. Quando o sistema conhece essa duração, o aliado recupera 1d6 PV ao receber apoio; sem idade conhecida, a fórmula não presume há quanto tempo o medo está ativo.","legado":"se @ALVO.condicao_tem_idade_amedrontado > 0 entao somar 1d6 em @USUARIO.vida","aliases":"condicao_idade_conhecida_<id>"},{"id":"096","origem":"contador_<nome>","modelo":"contador <nome>","formula":"se @USUARIO.contador brasas >= 4 entao subtrair 1d10 em @ALVO.vida","explicacao":"A forma contador_<nome> é um alias para o total do contador. Aqui, contador_brasas habilita uma explosão quando o personagem acumula pelo menos 4 brasas; com 3, não ativa. Troque brasas pelo identificador usado na ficha.","legado":"se @USUARIO.contador_brasas >= 4 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"097","origem":"cura_recebida","modelo":"cura recebida","formula":"se @ALVO.cura recebida >= 12 entao somar 1 em @USUARIO.sorte","explicacao":"Uma bênção responde a uma cura recente de 12 ou mais PV e concede 1 uso de Sorte a quem a lançou. Uma cura de 11 não atinge o limiar; 12 ou mais ativa o efeito. A chave registra a última cura recebida, não a soma do turno.","legado":"se @ALVO.cura_recebida >= 12 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"098","origem":"cura_recebida_nesta_rodada","modelo":"cura recebida nesta rodada","formula":"se @ALVO.cura recebida nesta rodada >= 20 entao somar 2 em @ALVO.defesa","explicacao":"Depois de receber ao menos 20 PV de cura na rodada, o paciente ganha +2 de Defesa pela estabilização mágica. Se recebeu 12 de cura e depois mais 8, a soma chega a 20 e ativa; 19 não. cura_recebida_nesta_rodada soma as curas do turno atual.","legado":"se @ALVO.cura_recebida_nesta_rodada >= 20 entao somar 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"099","origem":"dado_vida","modelo":"dado_vida","formula":"se @USUARIO.dado_vida > 0 entao subtrair 1 em @USUARIO.dado_vida, somar 1d8 + @USUARIO.atributo con em @USUARIO.vida","explicacao":"Durante um descanso curto, o personagem gasta um Dado de Vida e recupera 1d8 + Constituição. Com Constituição 2 e resultado 5, recupera 7 PV; sem dados disponíveis, a condição impede o gasto e a cura.","legado":"se @USUARIO.dado_vida > 0 entao subtrair 1 em @USUARIO.dado_vida, somar 1d8 + @USUARIO.con em @USUARIO.vida","aliases":"dado_vida_atual"},{"id":"100","origem":"dado_vida_max","modelo":"maximo dado_vida","formula":"somar @USUARIO.maximo dado_vida - @USUARIO.dado_vida em @USUARIO.dado_vida","explicacao":"Uma recuperação completa devolve os Dados de Vida gastos até o total máximo. Se o personagem tem 7 dados no limite e conserva 3, a fórmula recupera 4; se já tem os 7, não altera nada. O máximo pode acompanhar o nível sem um número fixo na regra.","legado":"somar @USUARIO.dado_vida_max - @USUARIO.dado_vida em @USUARIO.dado_vida","aliases":"nenhum listado"},{"id":"101","origem":"DANO","modelo":"dano base","formula":"subtrair @DANO.dano base + @USUARIO.treino em @ALVO.vida","explicacao":"No processamento de dano da arma, soma o dano-base recebido no contexto ao Treinamento do atacante. Se a arma calculou 7 e o Treinamento vale 2, o alvo perde 9 PV. Use @DANO para reaproveitar o resultado-base sem recalcular os dados da arma.","legado":"subtrair @DANO + @USUARIO.treino em @ALVO.vida","aliases":"nenhum listado"},{"id":"102","origem":"dano_recebido_nesta_rodada","modelo":"dano recebido rodada","formula":"se @USUARIO.dano recebido rodada >= 10 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma habilidade de retaliação desperta depois que o usuário sofreu pelo menos 10 de dano na rodada. Com 6 de um golpe e 4 de outro, o total chega a 10 e libera 1d8; com 9 acumulados, ainda não. vida_perdida_nesta_rodada é um alias aceito.","legado":"se @USUARIO.dano_recebido_nesta_rodada >= 10 entao subtrair 1d8 em @ALVO.vida","aliases":"vida_perdida_nesta_rodada"},{"id":"103","origem":"DANO.absorvido","modelo":"dano absorvido","formula":"somar floor(@DANO.dano absorvido / 5) em @USUARIO.pe","explicacao":"Uma armadura converte cada bloco completo de 5 pontos absorvidos em 1 PE. Se a diferença entre dano inicial e final for 12, recupera 2 PE; se for 4, recupera 0. O valor inclui todas as formas de absorção e não mede apenas a RD da ficha.","legado":"somar floor(@DANO.absorvido / 5) em @USUARIO.pe","aliases":"nenhum listado"},{"id":"104","origem":"DANO.alcance","modelo":"distancia ataque","formula":"se @DANO.distancia ataque <= 6 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma reação de curta distância funciona se a distância real entre as peças no início da resolução era de até 6 m. Um disparo a 5 m recebe 1d8 adicional; a 7 m não. Sem peças no mapa, o alcance fica ausente e a regra não deve presumir um valor.","legado":"se @DANO.alcance <= 6 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"105","origem":"DANO.foi_ataque_oportunidade","modelo":"dano foi ataque oportunidade","formula":"se @DANO.dano foi ataque oportunidade > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Um talento acrescenta 2d6 somente a ataques marcados como Ataque de Oportunidade antes da rolagem. Ataques comuns ficam sem esse bônus. A marca vem do painel do ataque, então o gatilho não depende de adivinhar pelo movimento do alvo.","legado":"se @DANO.foi_ataque_oportunidade > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"106","origem":"DANO.foi_critico","modelo":"dano foi critico","formula":"se @DANO.dano foi critico > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"Depois que o evento informa um acerto crítico, a runa acrescenta 2d8 de dano ao alvo. Se o evento informa um acerto normal, o marcador vale 0 e o adicional não acontece. A fórmula precisa ser avaliada com o contexto do evento de dano.","legado":"se @DANO.foi_critico > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"107","origem":"DANO.foi_falha_critica","modelo":"foi falha_critica","formula":"se @DANO.foi falha_critica > 0 entao somar 1 em @USUARIO.sorte","explicacao":"Uma regra de azar compensado devolve 1 uso de Sorte quando a resolução informa falha crítica. Vincule a fórmula ao evento de erro de ataque que fornece essa marca: erros não criam eventos de dano, portanto ela não deve depender de aoSofrerDano.","legado":"se @DANO.foi_falha_critica > 0 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"108","origem":"DANO.foi_furtivo","modelo":"foi dano furtivo","formula":"se @DANO.foi dano furtivo > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um ataque feito enquanto o personagem estava escondido recebe 2d8 adicionais se a resolução preservar a marca de furtividade. Um golpe frontal não tem essa marca e não ativa o dano extra. A condição usa o estado registrado pelo ataque, não apenas uma estimativa de distância.","legado":"se @DANO.foi_furtivo > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"109","origem":"DANO.fonte","modelo":"dano fonte <fonte do dano>","formula":"se @DANO.dano fonte feitico entao somar 2 em @USUARIO.defesa","explicacao":"Um manto antimagia concede +2 de Defesa quando a fonte do dano é um feitiço, código 2. Dano de arma (1), efeito Omni (3) ou ambiente (4) não ativa essa reação. A chave identifica a categoria que produziu o dano.","legado":"se @DANO.fonte = 2 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"110","origem":"DANO.tem_alvo","modelo":"tem alvo","formula":"se @DANO.tem alvo = 1 entao somar 1d8 em @ALVO.vida temporaria","explicacao":"Uma reação de escudo só concede 1d8 PV temporários quando a resolução identifica a ficha atingida. Se não existe entidade-alvo, como em certos efeitos de área sem vítima registrada, a fórmula não tenta aplicar o benefício a uma ficha inexistente.","legado":"se @DANO.tem_alvo = 1 entao somar 1d8 em @ALVO.vida_temp","aliases":"DANO.id_alvo"},{"id":"111","origem":"DANO.tem_atacante","modelo":"tem atacante","formula":"se @DANO.tem atacante = 1 entao subtrair 1 em @ALVO.ataques restantes","explicacao":"Uma marca de retaliação só consome um ataque restante quando o evento informa quem atacou. Com atacante presente, reduz a contagem do alvo em 1; sem essa informação, não altera a ficha. Isso evita atribuir uma resposta automática a dano ambiental.","legado":"se @DANO.tem_atacante = 1 entao subtrair 1 em @ALVO.ataques_restantes","aliases":"DANO.id_origem"},{"id":"112","origem":"DANO.tipo","modelo":"dano tipo <tipo do dano>","formula":"se @DANO.dano tipo DAL entao somar 2d6 em @USUARIO.vida temporaria","explicacao":"A proteção reativa concede 2d6 PV temporários quando o código do tipo de dano recebido é 9 (DAL, conforme a tabela do guia). Para outros códigos, como dano de arma ou fogo, a condição não ativa. O número representa a classificação do tipo, não uma quantidade de dano.","legado":"se @DANO.tipo = 9 entao somar 2d6 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"113","origem":"DANO.tipo_ataque","modelo":"dano tipo ataque","formula":"se @DANO.dano tipo ataque = 2 entao somar 2 em @ALVO.defesa","explicacao":"Uma capa balística reage a ataques à distância, identificados pelo código 2, e concede ao alvo +2 de Defesa para a resposta definida pela ficha. Código 1 é corpo a corpo e 3 é amaldiçoado; esses tipos não ativam este exemplo.","legado":"se @DANO.tipo_ataque = 2 entao somar 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"114","origem":"DANO.valor_final","modelo":"dano final","formula":"se @DANO.dano final >= 20 entao somar 1 em @USUARIO.sorte","explicacao":"Após a resolução completa, uma passiva concede 1 uso de Sorte se o dano final ficou em 20 ou mais. O valor já considera RD, imunidade, vulnerabilidade e PV temporários; dano bruto 24 reduzido a 18 não cumpre a condição.","legado":"se @DANO.valor_final >= 20 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"115","origem":"DANO.valor_inicial","modelo":"dano inicial","formula":"somar min(@DANO.dano inicial, 10) em @USUARIO.vida temporaria","explicacao":"Num pré-efeito defensivo, concede PV temporários iguais ao dano bruto recebido, limitados a 10. Se chegaram 14 pontos antes de mitigação, gera 10; se chegaram 6, gera 6. Esse valor é lido antes do pré-hook e da redução desta resolução.","legado":"somar min(@DANO.valor_inicial, 10) em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"116","origem":"defesa","modelo":"defesa","formula":"se @ALVO.defesa <= 12 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma manobra de abertura pune um alvo com guarda baixa. Se a Defesa dele for 12 ou menos, aplica 1d8; com Defesa 13, não dispara. A chave lê a defesa passiva do alvo e pode alimentar efeitos que dependem do quanto ele está protegido.","legado":"se @ALVO.defesa <= 12 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"117","origem":"defesa_cac","modelo":"defesa cac","formula":"se @ALVO.defesa cac <= 14 entao subtrair 1d10 em @ALVO.vida","explicacao":"Um golpe corpo a corpo especial encontra uma abertura quando a defesa CaC do alvo é 14 ou menos. Um defensor com 14 recebe 1d10; com 15, evita esse efeito. A chave separa a proteção contra golpes próximos da defesa geral.","legado":"se @ALVO.defesa_cac <= 14 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"118","origem":"defesa_dist","modelo":"defesa distancia","formula":"se @ALVO.defesa distancia <= 13 entao subtrair 2d6 em @ALVO.vida","explicacao":"Um disparo de cobertura atinge alvos cuja defesa contra ataques à distância seja 13 ou menor. Se a defesa à distância for 13, aplica 2d6; com 14, não passa pela condição. Esta leitura permite que uma habilidade interaja especificamente com proteção contra projéteis.","legado":"se @ALVO.defesa_dist <= 13 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"119","origem":"defesa_duas_armas","modelo":"bonus defesa duas_armas","formula":"somar @USUARIO.bonus defesa duas_armas em @USUARIO.defesa","explicacao":"Ao lutar com duas armas, aplica à Defesa exatamente o bônus que a ficha calcula para essa empunhadura. Se o bônus for +1, soma 1; se for +2, soma 2. A fórmula acompanha equipamentos e talentos que alterem o valor.","legado":"somar @USUARIO.defesa_duas_armas em @USUARIO.defesa","aliases":"dual_wield_def"},{"id":"120","origem":"des","modelo":"atributo des","formula":"subtrair 1d6 + @USUARIO.atributo des em @ALVO.vida","explicacao":"Use em um ataque ágil, como uma adaga arremessada: o dano combina 1d6 com a Destreza do personagem. Com Destreza 3 e resultado 5 no dado, são 8 pontos de dano. A fórmula consulta quem executa a ação, não o alvo.","legado":"subtrair 1d6 + @USUARIO.des em @ALVO.vida","aliases":"destreza"},{"id":"121","origem":"desarmado","modelo":"desarmado","formula":"se @USUARIO.desarmado > 0 entao subtrair 1d6 + @USUARIO.for em @ALVO.vida","explicacao":"Se o personagem está sem arma equipada, um golpe desarmado causa 1d6 mais Força. Com Força 3 e o dado mostrando 4, o dano é 7; ao equipar uma arma, a condição deixa de liberar este ataque de punho.","legado":"se @USUARIO.desarmado > 0 entao subtrair 1d6 + @USUARIO.for em @ALVO.vida","aliases":"nenhum listado"},{"id":"122","origem":"descoberto","modelo":"descoberto","formula":"se @USUARIO.descoberto > 0 entao somar 2 em @USUARIO.pericia percepcao","explicacao":"Uma lente de reconhecimento concede +2 em Percepção quando o slot de Venda está vazio, que é o estado representado por Descoberto. Se o slot estiver ocupado, a condição falha. Use a chave para regras que dependem de o personagem enxergar livremente.","legado":"se @USUARIO.descoberto > 0 entao somar 2 em @USUARIO.pericia_percepcao","aliases":"nenhum listado"},{"id":"123","origem":"desloc","modelo":"deslocamento","formula":"somar @USUARIO.deslocamento em @USUARIO.contador metros_taticos","explicacao":"No início de uma investida, esta linha repõe no contador metros_taticos os metros do deslocamento base. Se a criatura se desloca 9 m, acrescenta 9 m disponíveis; uma ficha com 6 m acrescenta 6. O exemplo usa o deslocamento como quantidade, sem embutir uma velocidade fixa. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"somar @USUARIO.desloc em @USUARIO.movimento_restante","aliases":"deslocamento"},{"id":"124","origem":"desvantagem_proxima_pericia","modelo":"desvantagem proxima pericia","formula":"se @USUARIO.desvantagem proxima pericia > 0 entao subtrair 2 em @USUARIO.pericia furtividade","explicacao":"Uma armadura barulhenta aplica -2 em Furtividade quando a próxima perícia está marcada com Desvantagem. Se a desvantagem é apenas para um ataque ou TR, a perícia de Furtividade não recebe a penalidade.","legado":"se @USUARIO.desvantagem_proxima_pericia > 0 entao subtrair 2 em @USUARIO.pericia_furtividade","aliases":"nenhum listado"},{"id":"125","origem":"desvantagem_proximo_ataque","modelo":"desvantagem proximo ataque","formula":"se @USUARIO.desvantagem proximo ataque > 0 entao subtrair 1d6 em @USUARIO.vida","explicacao":"Uma técnica instável causa 1d6 de dano ao próprio usuário se a próxima rolagem de ataque estiver marcada com Desvantagem. A penalidade aplicada a uma perícia ou TR não satisfaz esta chave específica de ataque.","legado":"se @USUARIO.desvantagem_proximo_ataque > 0 entao subtrair 1d6 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"126","origem":"desvantagem_proximo_tr","modelo":"desvantagem proximo tr","formula":"se @USUARIO.desvantagem proximo tr > 0 entao subtrair 2 em @USUARIO.fortitude","explicacao":"Uma toxina impõe -2 adicional em Fortitude se o próximo Teste de Resistência estiver marcado com Desvantagem. Se a desvantagem afeta outra rolagem, a condição não entra. O motor ainda resolve a rolagem com desvantagem.","legado":"se @USUARIO.desvantagem_proximo_tr > 0 entao subtrair 2 em @USUARIO.fortitude","aliases":"nenhum listado"},{"id":"127","origem":"dom","modelo":"aptidao dom","formula":"subtrair 1d10 + @USUARIO.aptidao dom em @ALVO.vida","explicacao":"Uma técnica de Domínio soma o valor DOM ao dano de 1d10. Com DOM 3 e resultado 7, aplica 10 de dano. A fórmula consulta a aptidão do usuário para dimensionar o efeito da técnica.","legado":"subtrair 1d10 + @USUARIO.dom em @ALVO.vida","aliases":"nenhum listado"},{"id":"128","origem":"duas_armas","modelo":"duas_armas","formula":"se @USUARIO.duas_armas > 0 entao somar 2 em @USUARIO.defesa","explicacao":"O estilo de duas armas concede +2 de Defesa enquanto o personagem realmente estiver com uma arma em cada mão. Com uma arma só, a condição vale 0 e não dá bônus. dual_wield é um alias aceito para essa chave.","legado":"se @USUARIO.duas_armas > 0 entao somar 2 em @USUARIO.defesa","aliases":"dual_wield"},{"id":"129","origem":"duas_maos","modelo":"duas_maos","formula":"se @USUARIO.duas_maos > 0 entao subtrair 1d12 + @USUARIO.for em @ALVO.vida","explicacao":"Uma arma pesada empunhada com as duas mãos causa 1d12 mais Força. Com Força 4 e resultado 7, causa 11; a fórmula só usa esse dado quando a mesma arma está nas mãos principal e secundária.","legado":"se @USUARIO.duas_maos > 0 entao subtrair 1d12 + @USUARIO.for em @ALVO.vida","aliases":"nenhum listado"},{"id":"130","origem":"duracao_turno_segundos","modelo":"duração turno segundos","formula":"se @USUARIO.duração turno segundos >= 60 entao somar 2 em @USUARIO.defesa","explicacao":"Uma postura de concentração concede +2 de Defesa em combates configurados com turnos de pelo menos 60 segundos. Com duração de 45 segundos, não ativa; com 60 ou mais, ativa.","legado":"se @USUARIO.duracao_turno_segundos >= 60 entao somar 2 em @USUARIO.defesa","aliases":"turno_duracao_seg"},{"id":"131","origem":"eh_inimigo","modelo":"eh inimigo","formula":"se @ALVO.eh inimigo > 0 entao subtrair 1d10 em @ALVO.vida","explicacao":"Um ataque de caça só causa o dano de 1d10 contra uma criatura classificada como inimigo. Aliados e NPCs neutros não satisfazem a condição, evitando que o mesmo efeito os atinja por engano.","legado":"se @ALVO.eh_inimigo > 0 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"132","origem":"eh_meu_turno","modelo":"eh meu turno","formula":"se @USUARIO.eh meu turno > 0 entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Uma barreira reativa concede 1d8 PV temporários somente no turno do próprio personagem. Enquanto outro participante age, o marcador é 0 e a fórmula não concede o escudo.","legado":"se @USUARIO.eh_meu_turno > 0 entao somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"133","origem":"eh_npc","modelo":"eh npc","formula":"se @ALVO.eh npc > 0 entao somar 2 em @USUARIO.sorte","explicacao":"Ao concluir uma missão com um NPC, o personagem recebe 2 usos de Sorte se a criatura observada estiver classificada como NPC. Um jogador ou inimigo não ativa a recompensa. O marcador permite adaptar interações conforme a categoria da ficha.","legado":"se @ALVO.eh_npc > 0 entao somar 2 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"134","origem":"eh_player","modelo":"eh player","formula":"se @ALVO.eh player > 0 entao somar 1d8 em @ALVO.vida","explicacao":"Uma habilidade de suporte restaura 1d8 PV apenas quando o alvo é um personagem jogador. A categoria PLAYER ativa a chave; NPCs e inimigos não recebem esta cura. Use o filtro quando a regra tratar fichas de jogador de modo diferente.","legado":"se @ALVO.eh_player > 0 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"135","origem":"em_combate","modelo":"em_combate","formula":"se @USUARIO.em_combate > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Uma postura defensiva só se arma quando o personagem está em um encontro ativo. Durante o combate, recebe +2 de Defesa; fora dele, o marcador vale 0 e não altera a ficha. Use a fórmula no início do combate ou na ativação da postura.","legado":"se @USUARIO.em_combate > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"136","origem":"em_terreno_dificil","modelo":"em_terreno_dificil","formula":"se @USUARIO.em_terreno_dificil > 0 entao subtrair 3 em @USUARIO.contador metros_taticos","explicacao":"Ao atravessar 1,5 m de lama profunda, o personagem gasta 3 m do contador metros_taticos, o dobro do custo normal. Em terreno comum, esta penalidade não entra. A chave é um marcador 1/0 separado do código numérico do terreno. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.em_terreno_dificil > 0 entao subtrair 3 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"137","origem":"empolgacao","modelo":"empolgacao","formula":"subtrair 1d6 + @USUARIO.empolgacao em @ALVO.vida","explicacao":"Um lutador transforma seu nível atual de Empolgação em força para o próximo golpe. No nível 2, com o d6 mostrando 4, causa 6 de dano; no nível 5, o mesmo resultado causa 9. O escalonamento acompanha os cinco níveis do estado.","legado":"subtrair 1d6 + @USUARIO.empolgacao em @ALVO.vida","aliases":"empolgacao_nivel"},{"id":"138","origem":"equipado_<id>","modelo":"item <id> equipado","formula":"se @USUARIO.item cota_de_malha equipado > 0 entao somar 4 em @USUARIO.defesa","explicacao":"Substitua <id> pelo identificador do equipamento; cota_de_malha é o exemplo. Enquanto a cota estiver equipada, concede +4 de Defesa; se estiver apenas guardada no inventário, não ativa o bônus.","legado":"se @USUARIO.equipado_cota_de_malha > 0 entao somar 4 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"139","origem":"er","modelo":"aptidao er","formula":"se @USUARIO.aptidao er >= 1 entao somar 2 em @USUARIO.contador espacos_expansao","explicacao":"Quando ER é pelo menos 1, registra dois espaços adicionais no contador espacos_expansao para uma regra de Expansão da mesa. ER 0 não concede espaços. Esse contador não altera automaticamente o limite nativo de concentração.","legado":"se @USUARIO.er >= 1 entao somar 2 em @USUARIO.concentracao_maxima","aliases":"nenhum listado"},{"id":"140","origem":"escudo_equipado","modelo":"escudo equipado","formula":"se @USUARIO.escudo equipado > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Uma manobra de guarda concede +2 de Defesa somente se o personagem estiver usando escudo e tiver a condição necessária para empunhá-lo. Sem escudo equipado, não recebe o bônus. A chave verifica o estado de equipamento durante a resolução.","legado":"se @USUARIO.escudo_equipado > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"141","origem":"escudo_id_equipado","modelo":"escudo [id] equipado","formula":"se @USUARIO.escudo sh-leve equipado > 0 entao somar 3 em @USUARIO.defesa","explicacao":"Uma técnica de bloqueio concede +3 de Defesa enquanto a ficha informa um escudo equipado. Sem escudo, não há bônus. Apesar do nome técnico conter id, a chave documentada é um marcador 1/0 de equipamento. Neste exemplo, sh-leve é o ID do Escudo Leve; outro escudo equipado não satisfaz essa consulta.","legado":"se @USUARIO.escudo_id_equipado > 0 entao somar 3 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"142","origem":"escudo_proficiente","modelo":"proficiencia escudo","formula":"se @USUARIO.proficiencia escudo > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Um estilo defensivo concede +2 de Defesa quando o personagem tem Proficiência com Escudo. Ter um escudo equipado sem o talento não satisfaz esta checagem; a chave testa a proficiência adquirida, que pode habilitar várias técnicas.","legado":"se @USUARIO.escudo_proficiente > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"143","origem":"especializacao_<id>","modelo":"especializacao <id>","formula":"se @USUARIO.especializacao duelista > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Troque <id> pelo identificador da especialização; duelista é o exemplo. Quem possui essa especialização acrescenta 1d8 ao golpe individual; uma ficha sem ela não recebe o dano extra.","legado":"se @USUARIO.especializacao_duelista > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"especializacao_id_<id>"},{"id":"144","origem":"esquiva","modelo":"esquiva","formula":"se @USUARIO.esquiva > 0 entao subtrair 1 em @USUARIO.esquiva, somar 1d8 em @USUARIO.vida","explicacao":"Neste sistema, Esquiva é o recurso legado que corresponde aos pontos de vida temporários da ficha. O exemplo consome 1 ponto dessa camada para ativar uma recuperação de 1d8 PV; se ela estiver zerada, não há custo disponível. Use a referência para mecânicas que ainda dependem desse recurso.","legado":"se @USUARIO.esquiva > 0 entao subtrair 1 em @USUARIO.esquiva, somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"145","origem":"esta_iluminado","modelo":"esta iluminado","formula":"se @ALVO.esta iluminado > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um disparo de luz concentrada causa 1d8 extra apenas contra um alvo iluminado por uma fonte visível. Se o alvo estiver na sombra, o efeito não entra. A chave consulta o estado de iluminação do alvo durante a ação.","legado":"se @ALVO.esta_iluminado > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"146","origem":"esta_no_mapa","modelo":"esta no mapa","formula":"se @USUARIO.esta no mapa > 0 entao somar 2 em @USUARIO.acerto","explicacao":"Um disparo coordenado recebe +2 de Acerto apenas se o personagem possui um token na cena ativa. Sem peça no mapa, a posição não é conhecida e o bônus de mira não pode ser aplicado.","legado":"se @USUARIO.esta_no_mapa > 0 entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"147","origem":"esta_oculto","modelo":"esta oculto","formula":"se @USUARIO.esta oculto > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Um ataque de emboscada acrescenta 2d6 se o atacante ainda estiver oculto do alvo no momento em que a ação é resolvida. Se a posição já foi revelada ou há linha de visão clara, o bônus não se aplica.","legado":"se @USUARIO.esta_oculto > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"148","origem":"exaustao","modelo":"exaustao","formula":"se @USUARIO.exaustao >= 3 entao subtrair 2 em @USUARIO.pericia atletismo","explicacao":"Uma regra de marcha impõe -2 em Atletismo a partir do terceiro nível de Exaustão. Com nível 2, a penalidade não se aplica; com nível 3 ou 4, aplica. O alias exaustao_nivel consulta o mesmo estado, permitindo reaproveitar a checagem.","legado":"se @USUARIO.exaustao >= 3 entao subtrair 2 em @USUARIO.pericia_atletismo","aliases":"exaustao_nivel, nivel_exaustao"},{"id":"149","origem":"flanqueado","modelo":"flanqueado","formula":"se @ALVO.flanqueado > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Dois ou mais inimigos adjacentes flanqueiam o alvo e abrem espaço para 2d6 de dano adicional. Um único oponente adjacente não basta. A chave resume a condição espacial que outra regra normalmente exigiria contar manualmente.","legado":"se @ALVO.flanqueado > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"150","origem":"foco_destruicao","modelo":"foco destruicao","formula":"se @USUARIO.foco destruicao > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"O personagem especializado em Destruição converte o foco em 2d8 de dano adicional. Se o foco escolhido for Economia ou Refino, este marcador vale 0 e o bônus ofensivo não se aplica.","legado":"se @USUARIO.foco_destruicao > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"151","origem":"foco_economia","modelo":"foco economia","formula":"se @USUARIO.foco economia > 0 entao somar 1 em @USUARIO.pe","explicacao":"Ao concluir uma conjuração, o foco em Economia devolve 1 PE como desconto da técnica. O efeito só se aplica a fichas cujo foco esteja configurado como Economia; use a fórmula uma vez por conjuração para não repetir o reembolso.","legado":"se @USUARIO.foco_economia > 0 entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"152","origem":"foco_refino","modelo":"foco refino","formula":"se @USUARIO.foco refino > 0 entao somar 2 em @USUARIO.acerto","explicacao":"Uma técnica de Refino ajusta a mira e concede +2 de Acerto ao próximo ataque mágico preparado. Com foco Refino, aplica o bônus; com outro foco, não. Configure o efeito como modificador temporário do ataque, para não deixar o bônus permanente na ficha.","legado":"se @USUARIO.foco_refino > 0 entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"153","origem":"fome","modelo":"fome","formula":"se @USUARIO.fome >= 18 entao subtrair 2 em @USUARIO.pericia sobrevivencia","explicacao":"Nesta regra, 18 ou mais pontos na escala de Fome indicam privação suficiente para impor -2 em Sobrevivência. Com 17, o personagem ainda não cruza o limite; com 18, a penalidade entra. O mesmo valor pode orientar outras regras de descanso ou consumo.","legado":"se @USUARIO.fome >= 18 entao subtrair 2 em @USUARIO.pericia_sobrevivencia","aliases":"fome_nivel"},{"id":"154","origem":"fonte_de_luz_ativa","modelo":"luz ativa","formula":"se @USUARIO.luz ativa > 0 entao somar 2 em @USUARIO.pericia percepcao","explicacao":"Uma lanterna ligada concede +2 em Percepção ao vasculhar uma sala escura. A chave vale 1 somente enquanto a fonte de luz carregada estiver ativa; uma lanterna apagada não revela detalhes nem concede o bônus.","legado":"se @USUARIO.fonte_de_luz_ativa > 0 entao somar 2 em @USUARIO.pericia_percepcao","aliases":"nenhum listado"},{"id":"155","origem":"for","modelo":"for","formula":"subtrair 1d8 + @USUARIO.for em @ALVO.vida","explicacao":"Exemplo de um golpe pesado com machado: a fórmula rola 1d8 e soma a Força de quem ataca. Se Força for 4 e o dado cair 6, o alvo perde 10 pontos de vida. A mesma chave pode alimentar qualquer efeito que escale com força física.","legado":"subtrair 1d8 + @USUARIO.for em @ALVO.vida","aliases":"forca"},{"id":"156","origem":"fortitude","modelo":"fortitude","formula":"se @ALVO.fortitude >= @CENA.dificuldade entao subtrair 1d8 em @ALVO.vida","explicacao":"Este é o ramo de sucesso de uma resistência contra veneno: Fortitude 15 contra CD 14 reduz a consequência a 1d8 de dano; abaixo da CD, a ação configurada pode aplicar o dano integral. A comparação usa o TR do alvo, não o atributo do atacante.","legado":"se @ALVO.fortitude >= @CENA.dificuldade entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"157","origem":"grupos_critico_arma","modelo":"quantidade grupos_arma critico_ampliado","formula":"subtrair 1d8 * @USUARIO.quantidade grupos_arma critico_ampliado em @ALVO.vida","explicacao":"Uma maestria causa 1d8 adicional por grupo de arma com crítico aprimorado. Se dois grupos atendem à regra e o d8 mostra 5, o bônus total é 10; com nenhum grupo, o termo resulta em zero. A chave conta grupos, não ataques.","legado":"subtrair 1d8 * @USUARIO.grupos_critico_arma em @ALVO.vida","aliases":"nenhum listado"},{"id":"158","origem":"hp_sacrificado","modelo":"vida sacrificada","formula":"se @USUARIO.vida sacrificada >= 10 entao subtrair 3d8 em @ALVO.vida","explicacao":"Um pacto libera uma explosão de 3d8 quando o personagem já sacrificou ao menos 10 PV em usos anteriores de Sacrifício pela Energia. Com 10 PV acumulados, o efeito é desbloqueado; com 9, não. O contador registra o total histórico, então esta fórmula usa esse investimento como requisito e não cobra os mesmos PV uma segunda vez.","legado":"se @USUARIO.hp_sacrificado >= 10 entao subtrair 3d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"159","origem":"imbuir_armado","modelo":"imbuir pendente","formula":"se @USUARIO.imbuir pendente > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"A arma recebe 2d6 de dano extra enquanto houver um feitiço pendente para imbuir o próximo golpe. Sem feitiço armado, a chave vale 0. Esta checagem lê o estado pendente; o consumo do feitiço deve ser feito pela ação ou pelo fluxo que resolve o ataque.","legado":"se @USUARIO.imbuir_armado > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"160","origem":"inconsciente","modelo":"inconsciente","formula":"se @ALVO.inconsciente > 0 entao subtrair 2d10 em @ALVO.vida","explicacao":"Um ataque de misericórdia usa a condição Inconsciente para liberar 2d10 de dano. O golpe especial só entra quando o alvo está inconsciente; estar ferido ou Morrendo não satisfaz essa checagem. A regra pode ser reaproveitada para ações que dependam desse estado.","legado":"se @ALVO.inconsciente > 0 entao subtrair 2d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"161","origem":"indice_turno_atual","modelo":"indice turno","formula":"se @USUARIO.indice turno = 0 entao somar 2 em @USUARIO.defesa","explicacao":"Uma sentinela ganha +2 de Defesa quando sua ação ocupa o primeiro índice da ordem: o índice começa em zero. Na posição seguinte, o valor é 1 e o bônus não ativa.","legado":"se @USUARIO.indice_turno_atual = 0 entao somar 2 em @USUARIO.defesa","aliases":"turno_atual_index"},{"id":"162","origem":"iniciativa","modelo":"iniciativa","formula":"subtrair 1d6 + @USUARIO.iniciativa em @ALVO.vida","explicacao":"Em uma regra caseira de emboscada, a vantagem de agir primeiro aumenta o dano de abertura. Com Iniciativa +3 e um d6 que resulta 4, o ataque causa 7. A chave oferece o valor configurado de iniciativa para efeitos que queiram escalonar com rapidez ou prontidão.","legado":"subtrair 1d6 + @USUARIO.iniciativa em @ALVO.vida","aliases":"nenhum listado"},{"id":"163","origem":"iniciativa_bonus","modelo":"bonus iniciativa","formula":"se @USUARIO.bonus iniciativa >= 4 entao somar 2 em @USUARIO.defesa","explicacao":"Um duelista com bônus de iniciativa +4 ou maior começa a luta em guarda e recebe +2 de Defesa nesta regra. O teste lê apenas o bônus configurado, não o resultado do dado; com bônus +3 não ativa.","legado":"se @USUARIO.iniciativa_bonus >= 4 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"164","origem":"iniciativa_rolagem","modelo":"rolagem iniciativa","formula":"se @USUARIO.rolagem iniciativa >= 18 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um resultado natural de iniciativa 18, 19 ou 20 libera um golpe de abertura de 2d8. Uma rolagem 17 não ativa, mesmo que o bônus torne a iniciativa total alta; esta chave é o valor do dado separado.","legado":"se @USUARIO.iniciativa_rolagem >= 18 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"165","origem":"iniciativa_total","modelo":"total iniciativa","formula":"se @USUARIO.total iniciativa >= 15 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um ataque de abertura causa 1d8 extra se o total de iniciativa do personagem foi 15 ou mais. Total 14 não basta; 15 ativa. A chave usa a soma já registrada de rolagem e bônus.","legado":"se @USUARIO.iniciativa_total >= 15 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"166","origem":"inimigo_adjacente","modelo":"tem inimigos adjacentes","formula":"se @USUARIO.tem inimigos adjacentes > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Uma guarda de duelo concede +2 de Defesa quando há ao menos um inimigo adjacente, a até 1,5 m. Sem inimigo próximo, o personagem não está em combate corpo a corpo e não recebe o bônus.","legado":"se @USUARIO.inimigo_adjacente > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"167","origem":"int","modelo":"int","formula":"subtrair 2d6 + @USUARIO.int em @ALVO.vida","explicacao":"Exemplo de um disparo arcano cuja potência depende de Inteligência: role 2d6 e some o atributo do conjurador. Com Inteligência 5 e dados totalizando 7, o efeito causa 12 de dano. Trocar o alvo ou o recurso não exige criar uma chave nova.","legado":"subtrair 2d6 + @USUARIO.int em @ALVO.vida","aliases":"inteligencia"},{"id":"168","origem":"integridade","modelo":"integridade","formula":"se @ALVO.integridade >= @CENA.dificuldade entao subtrair 1d6 em @ALVO.vida","explicacao":"Contra uma invasão psíquica de CD 16, Integridade 17 limita a consequência a 1d6; Integridade 15 não passa e pode receber o efeito completo definido no outro grau de sucesso. Use este TR para representar a firmeza da mente e da identidade.","legado":"se @ALVO.integridade >= @CENA.dificuldade entao subtrair 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"169","origem":"ITEM.usos_restantes","modelo":"usos restantes","formula":"se @ITEM.usos restantes >= 1 entao subtrair 1d8 em @ALVO.vida","explicacao":"A pistola rúnica ainda tem carga se Usos Restantes for pelo menos 1; nesse caso, o tiro causa 1d8 ao alvo. Com zero, a fórmula não libera o efeito. Configure também o custo usos_item: 1 na ação para consumir a carga ao ativar.","legado":"se @ITEM.usos_restantes >= 1 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"170","origem":"ITEM.usos_totais","modelo":"usos maximos","formula":"se @ITEM.usos maximos >= 3 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um artefato com capacidade para três ou mais cargas pode disparar seu modo de sobrecarga e causar 2d8. Um item com total máximo 2 não atende ao requisito. A chave lê a capacidade cadastrada para aquela cópia do item, não quantas cargas restam.","legado":"se @ITEM.usos_totais >= 3 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"171","origem":"linha_de_visao","modelo":"linha_de_visao","formula":"se @USUARIO.linha_de_visao > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um disparo de besta exige linha de visão entre o usuário e o alvo. Com o marcador em 1, causa 2d8; uma parede ou obstáculo que bloqueie a visão deixa o marcador em 0 e impede a execução do disparo.","legado":"se @USUARIO.linha_de_visao > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"172","origem":"metros_movidos","modelo":"metros movidos","formula":"se @USUARIO.metros movidos >= 6 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um ataque de investida ganha 1d8 adicional se o personagem já percorreu pelo menos 6 m neste turno. Com 5 m movidos, não ativa; ao completar 6 m, libera o bônus. A contagem zera conforme o turno e não mede a distância entre as peças.","legado":"se @USUARIO.metros_movidos >= 6 entao subtrair 1d8 em @ALVO.vida","aliases":"metros_movidos_neste_turno"},{"id":"173","origem":"metros_movidos_combate","modelo":"metros movidos combate","formula":"se @USUARIO.metros movidos combate >= 6 entao subtrair 1d8 em @ALVO.vida","explicacao":"Depois de correr pelo menos 6 m durante o combate, o personagem converte a corrida em um golpe de investida de 1d8. Com 5 m percorridos, ainda não alcança a distância exigida; a 6 m ou mais, libera o dano. Avalie ao concluir o movimento, não a cada atualização do arraste.","legado":"se @USUARIO.metros_movidos_combate >= 6 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"174","origem":"morrendo","modelo":"morrendo","formula":"se @ALVO.morrendo > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma habilidade de execução só dispara contra um alvo que já entrou no estado Morrendo. O valor 1 libera o dano de 1d8; em um alvo estável, a condição é falsa. Isso deixa o estado atual decidir quando uma habilidade especial pode ser usada.","legado":"se @ALVO.morrendo > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"esta_morrendo"},{"id":"175","origem":"morto","modelo":"morto","formula":"se @ALVO.morto = 0 entao somar 1d6 em @USUARIO.vida","explicacao":"Um vínculo necromântico só recupera 1d6 PV se a criatura observada ainda não estiver morta. Contra um alvo vivo, a condição permite a cura; depois da morte, não. A chave distingue o estado final de estar apenas inconsciente ou Morrendo.","legado":"se @ALVO.morto = 0 entao somar 1d6 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"176","origem":"movimento_disponivel","modelo":"movimento disponivel","formula":"se @USUARIO.movimento disponivel > 0 entao subtrair 1 em @USUARIO.contador metros_taticos","explicacao":"Um passo de reposicionamento só pode ser feito se ainda restar deslocamento neste turno. Com qualquer distância disponível, gasta 1 m; quando o orçamento chegou a zero, a ação não concede movimento extra. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.movimento_disponivel > 0 entao subtrair 1 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"177","origem":"movimento_restante","modelo":"movimento restante","formula":"se @USUARIO.movimento restante >= 3 entao subtrair 3 em @USUARIO.contador metros_taticos, somar 2 em @USUARIO.defesa","explicacao":"Um passo defensivo exige pelo menos 3 m de saldo de metros_taticos. Se houver 5 m, gasta 3 e concede +2 de Defesa; com apenas 2 m, a manobra não pode ser usada. A leitura evita permitir movimento extra além do orçamento atual. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.movimento_restante >= 3 entao subtrair 3 em @USUARIO.movimento_restante, somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"178","origem":"na_linha_de_frente","modelo":"adjacentes","formula":"se @USUARIO.adjacentes > 0 entao subtrair 1d8 + @USUARIO.for em @ALVO.vida","explicacao":"O combatente na linha de frente ganha um golpe de pressão quando pelo menos um inimigo está adjacente. Se não há inimigos a 1,5 m, a técnica não é liberada; quando há, causa 1d8 mais Força ao alvo escolhido.","legado":"se @USUARIO.na_linha_de_frente > 0 entao subtrair 1d8 + @USUARIO.for em @ALVO.vida","aliases":"nenhum listado"},{"id":"179","origem":"nivel","modelo":"nivel","formula":"somar floor(@USUARIO.nivel / 2) em @USUARIO.pe maximo","explicacao":"Uma característica de progressão aumenta o PE máximo em metade do nível, arredondada para baixo. No nível 7, acrescenta 3 ao limite; no nível 8, acrescenta 4. Como consulta o nível atual, a mesma regra acompanha o avanço do personagem.","legado":"somar floor(@USUARIO.nivel / 2) em @USUARIO.pe_max","aliases":"nenhum listado"},{"id":"180","origem":"numero_da_rodada","modelo":"rodada <número>","formula":"se @USUARIO.rodada >= 3 entao subtrair 1d8 em @ALVO.vida","explicacao":"A criatura acumula energia e libera uma rajada a partir da terceira rodada. Na rodada 2, o dano extra não acontece; na 3 ou em qualquer rodada posterior, causa 1d8. O número é o round atual do combate.","legado":"se @USUARIO.numero_da_rodada >= 3 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"181","origem":"ordem_na_iniciativa","modelo":"posicao iniciativa","formula":"se @USUARIO.posicao iniciativa = 1 entao somar 2 em @USUARIO.defesa","explicacao":"O combatente que ocupa a posição 1 na iniciativa ergue o escudo e ganha +2 de Defesa. O segundo personagem tem posição 2 e não ativa esta regra. Fora da ordem de combate, a chave vale 0.","legado":"se @USUARIO.ordem_na_iniciativa = 1 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"182","origem":"origem_<id>","modelo":"origem <id>","formula":"se @USUARIO.origem nobre > 0 entao somar 2 em @USUARIO.pericia persuasao","explicacao":"Substitua <id> pelo identificador da origem; neste caso, nobre. Um personagem com essa origem ganha +2 em Persuasão ao negociar com autoridades; outra origem não ativa o bônus. O nome exibido pode ser diferente do identificador técnico.","legado":"se @USUARIO.origem_nobre > 0 entao somar 2 em @USUARIO.pericia_persuasao","aliases":"origem_id_<id>"},{"id":"183","origem":"pe","modelo":"pe","formula":"subtrair 3 em @USUARIO.pe, subtrair 2d8 em @ALVO.vida","explicacao":"Exemplo de um raio que custa 3 pontos de energia e depois causa 2d8 de dano. A primeira instrução consome PE de quem conjura; a segunda reduz a vida do alvo. Use a leitura de pe para conferir recursos, criar custos condicionais ou calcular efeitos.","legado":"subtrair 3 em @USUARIO.pe, subtrair 2d8 em @ALVO.vida","aliases":"energia, energia_atual, pe_atual"},{"id":"184","origem":"pe_faltante","modelo":"pe faltante","formula":"somar min(@USUARIO.pe faltante, 4) em @USUARIO.pe","explicacao":"Uma bateria restaura até 4 PE, limitada pelo espaço que ainda falta até o máximo. Se faltarem 2, recupera 2; se faltarem 9, recupera 4. O min evita que a fórmula ultrapasse o limite de energia.","legado":"somar min(@USUARIO.pe_faltante, 4) em @USUARIO.pe","aliases":"nenhum listado"},{"id":"185","origem":"pe_faltante_pct","modelo":"porcentagem pe faltante","formula":"se @USUARIO.porcentagem pe faltante >= 0.5 entao somar 1d6 em @USUARIO.pe","explicacao":"Uma recarga de emergência fica disponível quando falta pelo menos metade da energia máxima. Com máximo 24 e 12 PE atuais, faltam 12 (50%) e a ação ativa; com 13 PE atuais, faltam 11 (aprox. 45,8%) e não ativa.","legado":"se @USUARIO.pe_faltante_pct >= 0.5 entao somar 1d6 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"186","origem":"pe_max","modelo":"pe maximo","formula":"somar ceil(@USUARIO.pe maximo * 0.1) em @USUARIO.pe","explicacao":"Uma fonte de energia recupera 10% do PE máximo, arredondando para cima. Um personagem com máximo 23 recebe 3 PE; com máximo 30, recebe 3. O cálculo se adapta à capacidade do personagem, em vez de restaurar sempre o mesmo número.","legado":"somar ceil(@USUARIO.pe_max * 0.1) em @USUARIO.pe","aliases":"energia_max"},{"id":"187","origem":"pe_maximo_feitico","modelo":"pe maximo feitico","formula":"se @USUARIO.pe maximo feitico >= 8 entao subtrair 2d10 em @ALVO.vida","explicacao":"Uma descarga de alto círculo só pode ser preparada por quem possui um feitiço cujo custo chega a 8 PE ou mais. Um grimório limitado a feitiços de até 7 PE não libera os 2d10; um feitiço de 8 PE ou mais satisfaz o requisito.","legado":"se @USUARIO.pe_maximo_feitico >= 8 entao subtrair 2d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"188","origem":"pe_minimo_feitico","modelo":"pe minimo feitico","formula":"se @USUARIO.pe minimo feitico > 0 e @USUARIO.pe minimo feitico <= 2 entao somar 1 em @USUARIO.pe","explicacao":"Uma disciplina de economia recompensa quem tem no grimório um feitiço de custo mínimo entre 1 e 2 PE. O teste exige custo maior que zero para não confundir uma lista vazia com um feitiço gratuito. Se o feitiço mais barato custa 3 PE, não ativa.","legado":"se @USUARIO.pe_minimo_feitico > 0 e @USUARIO.pe_minimo_feitico <= 2 entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"189","origem":"pe_pct","modelo":"porcentagem pe","formula":"se @USUARIO.porcentagem pe < 0.2 entao somar 2 em @USUARIO.pe","explicacao":"Uma técnica de foco recupera 2 PE quando o usuário está abaixo de 20% da energia máxima. Com máximo 30, 5 PE representam cerca de 16,7% e ativam a recuperação; 6 PE representam exatamente 20% e não passam pelo sinal de menor estrito. O alias energia_pct usa a mesma chave.","legado":"se @USUARIO.pe_pct < 0.2 entao somar 2 em @USUARIO.pe","aliases":"energia_pct"},{"id":"190","origem":"pe_pct_abaixo_25","modelo":"pe ate 25%","formula":"se @USUARIO.pe ate 25% > 0 entao somar 2d6 em @USUARIO.pe","explicacao":"Uma reserva de emergência se libera quando resta no máximo um quarto do PE máximo. Se o limite é 24, a chave ativa com 6 PE ou menos; com 7, não. A habilidade pode recuperar 2d6 sem usar um limite absoluto igual para todos.","legado":"se @USUARIO.pe_pct_abaixo_25 > 0 entao somar 2d6 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"191","origem":"pe_pct_abaixo_50","modelo":"pe ate 50%","formula":"se @USUARIO.pe ate 50% > 0 entao somar 1d8 em @USUARIO.pe","explicacao":"Uma técnica de respiração recupera 1d8 PE quando o usuário está com metade ou menos de sua energia máxima. Com máximo 30, 15 PE ativa a recuperação; 16 PE não. Assim, o limite acompanha a capacidade de cada ficha.","legado":"se @USUARIO.pe_pct_abaixo_50 > 0 entao somar 1d8 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"192","origem":"pe_sustentacao_por_rodada","modelo":"custo sustentacao rodada","formula":"se @USUARIO.custo sustentacao rodada > 0 entao subtrair min(@USUARIO.pe, @USUARIO.custo sustentacao rodada) em @USUARIO.pe","explicacao":"No pulso de manutenção, cobra o PE total dos buffs sustentados. Se dois efeitos custam 1 e 2 PE por rodada, o total é 3; com apenas 2 PE disponíveis, min limita a cobrança ao saldo. Configure a avaliação para ocorrer uma vez por rodada.","legado":"se @USUARIO.pe_sustentacao_por_rodada > 0 entao subtrair min(@USUARIO.pe, @USUARIO.pe_sustentacao_por_rodada) em @USUARIO.pe","aliases":"pe_por_rodada_sustentado"},{"id":"193","origem":"pe_temp","modelo":"pe temporario","formula":"se @USUARIO.pe temporario >= 2 entao subtrair 2 em @USUARIO.pe temporario, subtrair 2d6 em @ALVO.vida","explicacao":"Este disparo gasta 2 PE temporários antes de causar 2d6 de dano. Com 2 ou mais pontos temporários, a técnica pode ser paga por essa camada; com apenas 1, a condição falha. O PE temporário é consultado separadamente do PE normal.","legado":"se @USUARIO.pe_temp >= 2 entao subtrair 2 em @USUARIO.pe_temp, subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"194","origem":"pe_temp_por_rodada","modelo":"pe temporario rodada","formula":"somar @USUARIO.pe temporario rodada em @USUARIO.pe temporario","explicacao":"No começo de cada rodada, o personagem recebe a quantidade configurada de PE temporário. Com valor 2, acrescenta 2 PE temporários para aptidões; com valor 0, nada é gerado. Separar essa reserva do PE normal permite regras de duração curta.","legado":"somar @USUARIO.pe_temp_por_rodada em @USUARIO.pe_temp","aliases":"nenhum listado"},{"id":"195","origem":"pericia_acrobacia","modelo":"pericia acrobacia","formula":"se @USUARIO.pericia acrobacia > @ALVO.acerto entao somar 1d6 em @USUARIO.vida temporaria","explicacao":"Ao escapar de um golpe, a Acrobacia do personagem precisa superar o Acerto do atacante para ganhar uma camada de proteção de 1d6 PV temporários. Acrobacia 8 contra Acerto 7 ativa o efeito; empate não, pois a comparação é estritamente maior.","legado":"se @USUARIO.pericia_acrobacia > @ALVO.acerto entao somar 1d6 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"196","origem":"pericia_atletismo","modelo":"pericia atletismo","formula":"se @USUARIO.pericia atletismo >= @ALVO.pericia atletismo entao subtrair 1d8 em @ALVO.vida","explicacao":"Numa disputa para empurrar um guarda para longe, compare o Atletismo de quem tenta a manobra com o Atletismo do alvo. Se o atacante tiver 6 contra 4, a condição libera 1d8 de impacto; com 3 contra 4, não. A fórmula pressupõe que esses valores já representam os bônus das fichas.","legado":"se @USUARIO.pericia_atletismo >= @ALVO.pericia_atletismo entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"197","origem":"pericia_direcao","modelo":"pericia direcao","formula":"se @USUARIO.pericia direcao >= @CENA.dificuldade entao somar 3 em @USUARIO.contador metros_taticos","explicacao":"Numa perseguição, Direção 14 contra CD 12 permite fazer uma curva segura e ganhar 3 m de avanço no veículo; 11 falha e não ganha distância. A chave usa a perícia de condução para transformar o teste em posição tática. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.pericia_direcao >= @CENA.dificuldade entao somar 3 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"198","origem":"pericia_enganacao","modelo":"pericia enganacao","formula":"se @USUARIO.pericia enganacao > @ALVO.pericia intuicao entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma finta verbal abre espaço para um ataque surpresa quando Enganação supera a Intuição do alvo. Enganação 8 contra Intuição 6 ativa 1d8 de dano; o empate não é suficiente. Isso representa o valor da perícia numa manobra, sem criar uma key especial para fintas.","legado":"se @USUARIO.pericia_enganacao > @ALVO.pericia_intuicao entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"199","origem":"pericia_feiticaria","modelo":"pericia feiticaria","formula":"se @USUARIO.pericia feiticaria >= @CENA.dificuldade entao subtrair 2d8 em @ALVO.vida","explicacao":"Para conjurar um selo de ataque, compare Feitiçaria com a dificuldade definida pelo Mestre. Feitiçaria 15 contra CD 14 libera 2d8 de dano; 13 contra CD 14 não. Altere a CD da cena para reaproveitar o exemplo em encontros diferentes.","legado":"se @USUARIO.pericia_feiticaria >= @CENA.dificuldade entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"200","origem":"pericia_furtividade","modelo":"pericia furtividade","formula":"se @USUARIO.pericia furtividade > @ALVO.pericia percepcao entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma emboscada só pega o alvo desprevenido se a Furtividade do usuário superar a Percepção dele. Furtividade 9 contra Percepção 7 libera 2d6 de dano; contra Percepção 9, o empate não basta. O valor comparado é o bônus total de cada ficha.","legado":"se @USUARIO.pericia_furtividade > @ALVO.pericia_percepcao entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"201","origem":"pericia_historia","modelo":"pericia historia","formula":"se @USUARIO.pericia historia >= @CENA.dificuldade entao somar 1 em @USUARIO.sorte","explicacao":"Ao reconhecer o brasão de uma família antiga, História igual ou maior que a CD revela uma pista que concede 1 uso de Sorte. Resultado 14 contra CD 14 passa; 13 falha. A consequência pode ser trocada mantendo a mesma verificação histórica.","legado":"se @USUARIO.pericia_historia >= @CENA.dificuldade entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"202","origem":"pericia_intimidacao","modelo":"pericia intimidacao","formula":"se @USUARIO.pericia intimidacao >= @ALVO.vontade entao aplicar amedrontado rodadas 1","explicacao":"Uma ameaça intimidadora aplica Amedrontado por uma rodada se Intimidação igualar ou superar a Vontade do alvo. Intimidação 7 contra Vontade 7 passa; 6 contra 7 não. O efeito usa a condição existente e a duração está explícita.","legado":"se @USUARIO.pericia_intimidacao >= @ALVO.vontade entao aplicar amedrontado rodadas 1","aliases":"nenhum listado"},{"id":"203","origem":"pericia_intuicao","modelo":"pericia intuicao","formula":"se @USUARIO.pericia intuicao >= @ALVO.pericia enganacao entao somar 2 em @USUARIO.acerto","explicacao":"Ao perceber que o adversário está blefando, compare Intuição com Enganação. Intuição 7 contra Enganação 5 revela a finta e dá +2 de Acerto no contra-ataque; contra Enganação 8, o usuário continua enganado.","legado":"se @USUARIO.pericia_intuicao >= @ALVO.pericia_enganacao entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"204","origem":"pericia_investigacao","modelo":"pericia investigacao","formula":"se @USUARIO.pericia investigacao >= @CENA.dificuldade entao somar 2 em @USUARIO.reserva pe","explicacao":"Na busca por uma sala oculta, Investigação 17 contra CD 15 encontra um estojo com 2 PE armazenados na reserva; 14 não encontra. O exemplo transforma o sucesso em um recurso concreto e usa a dificuldade atual da cena.","legado":"se @USUARIO.pericia_investigacao >= @CENA.dificuldade entao somar 2 em @USUARIO.reserva_pe","aliases":"nenhum listado"},{"id":"205","origem":"pericia_medicina","modelo":"pericia medicina","formula":"se @USUARIO.pericia medicina >= @CENA.dificuldade entao somar 2d8 em @ALVO.vida","explicacao":"Durante os primeiros socorros, Medicina 15 contra CD 13 restaura 2d8 PV do paciente; 12 não estabiliza o ferimento a tempo. A cura vai para a ficha do alvo, enquanto a CD permite ao Mestre graduar a gravidade do caso.","legado":"se @USUARIO.pericia_medicina >= @CENA.dificuldade entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"206","origem":"pericia_ocultismo","modelo":"pericia ocultismo","formula":"se @USUARIO.pericia ocultismo >= @CENA.dificuldade entao subtrair 2d8 em @ALVO.vida","explicacao":"Ao identificar uma marca amaldiçoada, Ocultismo 16 contra CD 14 permite inverter o símbolo e causar 2d8 à entidade ligada a ele; 13 falha. A chave pode orientar também identificar, conter ou desfazer fenômenos sobrenaturais.","legado":"se @USUARIO.pericia_ocultismo >= @CENA.dificuldade entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"207","origem":"pericia_oficio1","modelo":"pericia oficio1","formula":"se @USUARIO.pericia oficio1 >= @CENA.dificuldade entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Se o grupo usa Ofício 1 como ferraria, um teste bem-sucedido para reforçar a armadura concede 1d8 PV temporários ao usuário. Com perícia 12 contra CD 11, a proteção é aplicada; contra CD 13, não. O Mestre pode definir Ofício 1 para outra especialidade na ficha.","legado":"se @USUARIO.pericia_oficio1 >= @CENA.dificuldade entao somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"208","origem":"pericia_oficio2","modelo":"pericia oficio2","formula":"se @USUARIO.pericia oficio2 >= @CENA.dificuldade entao somar 1 em @USUARIO.pe","explicacao":"Neste exemplo, Ofício 2 representa a fabricação de talismãs. Com resultado 16 contra CD 15, a peça recupera 1 PE de quem a preparou; com 14, os materiais se perdem sem recuperar energia. O identificador técnico continua genérico para a especialidade configurada pelo grupo.","legado":"se @USUARIO.pericia_oficio2 >= @CENA.dificuldade entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"209","origem":"pericia_oficio3","modelo":"pericia oficio3","formula":"se @USUARIO.pericia oficio3 >= @CENA.dificuldade entao somar 1d6 em @ALVO.vida","explicacao":"Aqui, Ofício 3 representa culinária de campo: preparar uma refeição nutritiva restaura 1d6 PV de um aliado. Ofício 3 igual ou maior que a CD libera a refeição; abaixo da CD, ela não fica pronta a tempo. A ficha decide qual especialidade cada Ofício representa.","legado":"se @USUARIO.pericia_oficio3 >= @CENA.dificuldade entao somar 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"210","origem":"pericia_percepcao","modelo":"pericia percepcao","formula":"se @USUARIO.pericia percepcao >= @ALVO.pericia furtividade entao somar 2 em @USUARIO.acerto","explicacao":"Um sentinela compara Percepção com a Furtividade do invasor. Com 8 contra 6, percebe a aproximação e ganha +2 de Acerto no primeiro disparo; com 5 contra 7, o alvo permanece escondido.","legado":"se @USUARIO.pericia_percepcao >= @ALVO.pericia_furtividade entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"211","origem":"pericia_performance","modelo":"pericia performance","formula":"se @USUARIO.pericia performance >= @CENA.dificuldade entao somar 1d6 em @ALVO.vida","explicacao":"Uma apresentação inspiradora anima um aliado e restaura 1d6 PV se Performance vencer a dificuldade. Performance 15 contra CD 13 funciona; 12 não alcança o público. O exemplo mostra um uso de apoio para a perícia, em vez de limitar Performance a entretenimento.","legado":"se @USUARIO.pericia_performance >= @CENA.dificuldade entao somar 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"212","origem":"pericia_persuasao","modelo":"pericia persuasao","formula":"se @USUARIO.pericia persuasao >= @ALVO.pericia intuicao entao somar 2 em @ALVO.vida temporaria","explicacao":"Durante uma negociação tensa, Persuasão igual ou maior que a Intuição do aliado o convence a continuar lutando e concede 2 PV temporários como ânimo renovado. Persuasão 8 contra Intuição 6 passa; Persuasão 5 contra Intuição 6 não. A fórmula e a explicação apontam para a mesma proteção temporária.","legado":"se @USUARIO.pericia_persuasao >= @ALVO.pericia_intuicao entao somar 2 em @ALVO.vida_temp","aliases":"nenhum listado"},{"id":"213","origem":"pericia_prestidigitacao","modelo":"pericia prestidigitacao","formula":"se @USUARIO.pericia prestidigitacao >= @ALVO.pericia percepcao entao somar 2 em @USUARIO.acerto","explicacao":"Durante uma finta com uma moeda, Prestidigitação igual ou maior que a Percepção do oponente cria uma abertura e concede +2 de Acerto ao usuário. Com 6 contra 6, a finta funciona; com 5 contra 6, o inimigo percebe o truque.","legado":"se @USUARIO.pericia_prestidigitacao >= @ALVO.pericia_percepcao entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"214","origem":"pericia_sobrevivencia","modelo":"pericia sobrevivencia","formula":"se @USUARIO.pericia sobrevivencia >= @CENA.dificuldade entao somar 1d8 em @USUARIO.vida","explicacao":"Ao encontrar ervas e água potável, Sobrevivência 13 contra CD 12 recupera 1d8 PV durante o descanso; 11 não encontra suprimentos seguros. O valor da dificuldade pode subir em um deserto ou cair numa floresta conhecida.","legado":"se @USUARIO.pericia_sobrevivencia >= @CENA.dificuldade entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"215","origem":"pericia_tecnologia","modelo":"pericia tecnologia","formula":"se @USUARIO.pericia tecnologia >= @CENA.dificuldade entao somar 2 em @USUARIO.contador metros_taticos","explicacao":"Ao desativar um bloqueio eletrônico, Tecnologia 13 contra CD 12 abre a passagem e economiza 2 m do deslocamento necessário; 11 contra CD 12 falha e não altera o orçamento. O exemplo liga o resultado do teste a uma vantagem tática imediata. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.pericia_tecnologia >= @CENA.dificuldade entao somar 2 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"216","origem":"pericia_teologia","modelo":"pericia teologia","formula":"se @USUARIO.pericia teologia >= @CENA.dificuldade entao subtrair 2d6 em @ALVO.vida","explicacao":"Durante um exorcismo, Teologia 18 contra CD 16 permite atingir a entidade com 2d6 de dano sagrado; 15 não alcança a dificuldade. O mesmo teste pode servir para identificar ritos ou afastar uma presença, mudando apenas o efeito após o sucesso.","legado":"se @USUARIO.pericia_teologia >= @CENA.dificuldade entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"217","origem":"pode_ser_curado","modelo":"cura permitida","formula":"se @ALVO.cura permitida > 0 entao somar 2d8 em @ALVO.vida","explicacao":"Uma magia de socorro restaura 2d8 PV apenas se o alvo estiver abaixo da Vida Máxima e não estiver morto nem Morrendo. Um personagem com 18/30 PV pode ser curado; com 30/30 ou em estado incompatível, não.","legado":"se @ALVO.pode_ser_curado > 0 entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"218","origem":"pre","modelo":"pre","formula":"subtrair 1d6 + @USUARIO.pre em @ALVO.vida","explicacao":"Exemplo de uma técnica de pressão espiritual que converte Presença em impacto: role 1d6 e some o atributo de quem a ativa. Se Presença for 4 e o dado sair 3, são 7 pontos de dano. Em outra habilidade, a mesma chave pode escalar intimidação, proteção de aliados ou qualquer outro valor.","legado":"subtrair 1d6 + @USUARIO.pre em @ALVO.vida","aliases":"car, carisma, presenca"},{"id":"219","origem":"prono","modelo":"prono","formula":"se @ALVO.prono > 0 entao subtrair 1d10 em @ALVO.vida","explicacao":"Um golpe de finalização acrescenta 1d10 contra um alvo caído/prono. Se a criatura estiver de pé, não recebe esse dano extra. A chave verifica a postura atual do alvo, permitindo usar a mesma manobra contra qualquer ficha.","legado":"se @ALVO.prono > 0 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"220","origem":"qtd_aliados_adjacentes","modelo":"quantidade aliados adjacentes","formula":"se @USUARIO.quantidade aliados adjacentes >= 2 entao somar 2 em @USUARIO.defesa","explicacao":"Uma guarda em formação concede +2 de Defesa quando pelo menos dois aliados estão adjacentes, a até 1,5 m. Um aliado ao lado não basta; dois ou mais fecham a linha defensiva.","legado":"se @USUARIO.qtd_aliados_adjacentes >= 2 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"221","origem":"qtd_aliados_proximos","modelo":"quantidade aliados proximos","formula":"somar @USUARIO.quantidade aliados proximos em @USUARIO.vida temporaria","explicacao":"Um estandarte concede 1 PV temporário por aliado a até 6 m. Com três aliados próximos, acrescenta 3; se ninguém estiver no raio, acrescenta 0. O alcance é maior que adjacência e favorece formações compactas.","legado":"somar @USUARIO.qtd_aliados_proximos em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"222","origem":"qtd_aptidoes","modelo":"quantidade aptidoes","formula":"subtrair 1d6 + @USUARIO.quantidade aptidoes em @ALVO.vida","explicacao":"Um ataque que converte domínio técnico em potência soma ao d6 o número de aptidões adquiridas. Com quatro aptidões e resultado 3, causa 7; com seis aptidões, causa 9 no mesmo resultado. Use quando a regra realmente escala pela quantidade escolhida.","legado":"subtrair 1d6 + @USUARIO.qtd_aptidoes em @ALVO.vida","aliases":"nenhum listado"},{"id":"223","origem":"qtd_aptidoes_aura","modelo":"quantidade aptidoes aura","formula":"se @USUARIO.quantidade aptidoes aura >= 2 entao somar 3 em @USUARIO.defesa","explicacao":"Uma sinergia protetora concede +3 de Defesa quando o personagem escolheu ao menos duas aptidões da família Aura. Uma aptidão não alcança o requisito; duas ou mais liberam o efeito. A contagem específica distingue essa família das demais aptidões.","legado":"se @USUARIO.qtd_aptidoes_aura >= 2 entao somar 3 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"224","origem":"qtd_buffs_ativos","modelo":"quantidade buffs ativos","formula":"se @USUARIO.quantidade buffs ativos >= 2 entao somar 2 em @USUARIO.defesa","explicacao":"Uma couraça arcana reforça a Defesa em +2 quando dois ou mais buffs estão ativos ao mesmo tempo. Um único efeito ativo não alcança o limiar. Diferente da contagem de feitiços conhecidos, esta chave consulta a lista de buffs atualmente aplicados.","legado":"se @USUARIO.qtd_buffs_ativos >= 2 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"225","origem":"qtd_buffs_sustentados","modelo":"quantidade buffs sustentados","formula":"se @USUARIO.quantidade buffs sustentados >= 2 entao subtrair 1d8 em @ALVO.vida","explicacao":"Manter dois encantamentos sustentados simultaneamente permite canalizar a energia excedente em uma rajada de 1d8 contra o alvo. Um buff instantâneo ou não sustentado não conta; são considerados apenas os ativos com isSustained.","legado":"se @USUARIO.qtd_buffs_sustentados >= 2 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"226","origem":"qtd_concentrando","modelo":"quantidade concentracao","formula":"se @USUARIO.quantidade concentracao >= 2 entao subtrair 1 em @USUARIO.pe","explicacao":"Uma técnica de sobrecarga custa 1 PE quando o personagem já mantém dois ou mais efeitos de concentração. Com um efeito ativo, não cobra esse custo extra; com dois, cobra. A chave conta efeitos ativos, não o limite máximo de espaços.","legado":"se @USUARIO.qtd_concentrando >= 2 entao subtrair 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"227","origem":"qtd_condicoes","modelo":"quantidade condicoes","formula":"se @USUARIO.quantidade condicoes >= 3 entao somar 2 em @USUARIO.defesa","explicacao":"Uma passiva de resistência concede +2 de Defesa quando o personagem carrega três ou mais condições ativas. Com duas, não ativa; com três, ativa. A contagem considera todas as categorias de condição, não apenas as físicas.","legado":"se @USUARIO.qtd_condicoes >= 3 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"228","origem":"qtd_condicoes_fisica","modelo":"quantidade condicoes fisicas","formula":"se @USUARIO.quantidade condicoes fisicas >= 2 entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Um talento de resistência física concede 1d8 PV temporários quando há pelo menos duas condições físicas ativas, como Sangrando e Queimando. Uma condição só não basta; a chave conta apenas as condições classificadas como FÍSICA.","legado":"se @USUARIO.qtd_condicoes_fisica >= 2 entao somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"229","origem":"qtd_condicoes_incapacitacao","modelo":"quantidade condicoes incapacitacao","formula":"se @ALVO.quantidade condicoes incapacitacao > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"Um golpe de execução causa 2d8 adicionais se o alvo já tiver ao menos uma condição de Incapacitação, como Atordoado ou Paralisado. Sem condição nessa categoria, o ataque não recebe o bônus.","legado":"se @ALVO.qtd_condicoes_incapacitacao > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"230","origem":"qtd_condicoes_mental","modelo":"quantidade condicoes mentais","formula":"se @ALVO.quantidade condicoes mentais >= 2 entao somar 2 em @ALVO.vontade","explicacao":"Uma técnica de foco concede +2 em Vontade ao alvo quando ele está sob duas ou mais condições mentais, ajudando-o a resistir à próxima influência. Com apenas uma condição mental, o bônus não é aplicado.","legado":"se @ALVO.qtd_condicoes_mental >= 2 entao somar 2 em @ALVO.vontade","aliases":"nenhum listado"},{"id":"231","origem":"qtd_condicoes_movimento","modelo":"quantidade condicoes movimento","formula":"se @ALVO.quantidade condicoes movimento > 0 entao subtrair 2 em @ALVO.defesa","explicacao":"Um ataque de cerco impõe -2 de Defesa contra um alvo cuja movimentação esteja comprometida por ao menos uma condição da categoria MOVIMENTO. Sem condição desse grupo, não há penalidade.","legado":"se @ALVO.qtd_condicoes_movimento > 0 entao subtrair 2 em @ALVO.defesa","aliases":"nenhum listado"},{"id":"232","origem":"qtd_condicoes_sensorial","modelo":"quantidade condicoes sensoriais","formula":"se @ALVO.quantidade condicoes sensoriais > 0 entao somar 2 em @USUARIO.pericia furtividade","explicacao":"Um infiltrador aproveita uma condição sensorial do guarda, como Cego ou Surdo, para receber +2 em Furtividade. A chave só conta condições classificadas como SENSORIAL; uma condição física isolada não ativa o bônus.","legado":"se @ALVO.qtd_condicoes_sensorial > 0 entao somar 2 em @USUARIO.pericia_furtividade","aliases":"nenhum listado"},{"id":"233","origem":"qtd_condicoes_vulnerabilidade","modelo":"quantidade condicoes vulnerabilidade","formula":"se @ALVO.quantidade condicoes vulnerabilidade > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma arma elemental causa 2d6 adicionais contra um alvo com pelo menos uma condição da categoria VULNERABILIDADE, como Exposto. Sem vulnerabilidade ativa, aplica apenas o dano normal da arma.","legado":"se @ALVO.qtd_condicoes_vulnerabilidade > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"234","origem":"qtd_contadores","modelo":"quantidade contadores","formula":"se @USUARIO.quantidade contadores >= 3 entao somar 2 em @USUARIO.pericia investigacao","explicacao":"Uma investigação ganha +2 quando a ficha mantém pelo menos três contadores nomeados, como pistas, suspeitos e locais examinados. Com dois contadores não ativa; com três, ativa. A chave conta registros, não os valores guardados neles.","legado":"se @USUARIO.qtd_contadores >= 3 entao somar 2 em @USUARIO.pericia_investigacao","aliases":"qtd_contadores_omni"},{"id":"235","origem":"qtd_desvantagens","modelo":"quantidade desvantagens","formula":"se @USUARIO.quantidade desvantagens >= 2 entao subtrair 2 em @USUARIO.acerto","explicacao":"Se dois ou mais modificadores de Desvantagem atingem o ataque, a técnica aplica uma penalidade adicional de -2 de Acerto. Com apenas uma fonte, não acumula essa penalidade. Use a contagem para distinguir uma dificuldade isolada de várias condições simultâneas.","legado":"se @USUARIO.qtd_desvantagens >= 2 entao subtrair 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"236","origem":"qtd_feiticos","modelo":"quantidade feiticos","formula":"se @USUARIO.quantidade feiticos >= 5 entao subtrair 2d8 em @ALVO.vida","explicacao":"Uma escola de magia exige cinco feitiços conhecidos para executar a descarga arcana de 2d8. Um grimório com 4 feitiços não libera o efeito; com 5 ou mais, libera. O total considera todos os feitiços registrados na ficha, não apenas os preparados.","legado":"se @USUARIO.qtd_feiticos >= 5 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"237","origem":"qtd_feiticos_buff","modelo":"quantidade feiticos buff","formula":"se @USUARIO.quantidade feiticos buff >= 2 entao somar 2 em @USUARIO.defesa","explicacao":"Uma especialização em encantamentos defensivos concede +2 de Defesa quando o grimório contém dois ou mais feitiços classificados como buff. Um único buff não basta. A contagem vem dos feitiços registrados, independentemente de estarem ativos agora.","legado":"se @USUARIO.qtd_feiticos_buff >= 2 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"238","origem":"qtd_feiticos_condicao","modelo":"quantidade feiticos condicao","formula":"se @USUARIO.quantidade feiticos condicao >= 1 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um foco de controle exige ao menos um feitiço que aplique condições e acrescenta 1d8 ao efeito contra o alvo atual. Com nenhum feitiço de condição conhecido, o adicional não entra; com um ou mais, entra. A chave conta a categoria condition do grimório.","legado":"se @USUARIO.qtd_feiticos_condicao >= 1 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"239","origem":"qtd_feiticos_cura","modelo":"quantidade feiticos cura","formula":"se @USUARIO.quantidade feiticos cura > 0 entao somar 1d8 em @ALVO.vida","explicacao":"Uma bênção de curandeiro fortalece em 1d8 a cura lançada pelo personagem se ele conhecer pelo menos um feitiço de cura. O exemplo usa o card dentro do efeito de cura dirigido ao aliado; a chave conta feitiços classificados como heal.","legado":"se @USUARIO.qtd_feiticos_cura > 0 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"240","origem":"qtd_feiticos_dano","modelo":"quantidade feiticos dano","formula":"se @USUARIO.quantidade feiticos dano >= 3 entao subtrair 2d6 em @ALVO.vida","explicacao":"Um talento de artilharia mágica exige ao menos três feitiços classificados como dano e acrescenta 2d6 ao disparo atual. Com 2 feitiços ofensivos, não ativa; com 3, ativa. A chave conta spellType damage na ficha.","legado":"se @USUARIO.qtd_feiticos_dano >= 3 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"241","origem":"qtd_feiticos_prontos","modelo":"quantidade feiticos prontos","formula":"se @USUARIO.quantidade feiticos prontos >= 2 entao subtrair 2d8 em @ALVO.vida","explicacao":"Uma sequência de batalha só fica disponível quando há pelo menos dois feitiços preparados para uso imediato. Com 1 preparado, a fórmula não libera o ataque de 2d8; com 2, libera. Feitiços conhecidos mas não preparados não entram nessa contagem.","legado":"se @USUARIO.qtd_feiticos_prontos >= 2 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"242","origem":"qtd_feiticos_tipo_<tipo>","modelo":"quantidade feiticos elemento <tipo>","formula":"se @USUARIO.quantidade feiticos elemento fogo >= 2 entao subtrair 2d6 em @ALVO.vida","explicacao":"Troque <tipo> pelo tipo de dano normalizado; neste exemplo, fogo. Dois feitiços de fogo no grimório liberam 2d6 adicionais; um ou nenhum não satisfaz o requisito. O campo conta feitiços conhecidos desse tipo, não apenas os preparados.","legado":"se @USUARIO.qtd_feiticos_tipo_fogo >= 2 entao subtrair 2d6 em @ALVO.vida","aliases":"qtd_feiticos_elemento_<tipo>"},{"id":"243","origem":"qtd_flags","modelo":"quantidade flags","formula":"se @USUARIO.quantidade flags >= 3 entao somar 2 em @USUARIO.pericia persuasao","explicacao":"Uma reputação registrada em pelo menos três flags personalizadas da ficha concede +2 em Persuasão ao negociar com os guardas. Duas flags não bastam; três ou mais ativam. A chave conta flags, sem somar seus valores.","legado":"se @USUARIO.qtd_flags >= 3 entao somar 2 em @USUARIO.pericia_persuasao","aliases":"qtd_flags_omni"},{"id":"244","origem":"qtd_fundamentos","modelo":"quantidade fundamentos","formula":"se @USUARIO.quantidade fundamentos > 0 entao subtrair @USUARIO.quantidade fundamentos * 1d6 em @ALVO.vida","explicacao":"A técnica combina um dado por fundamento configurado. Com 3 fundamentos, rola 3d6; com 1, rola 1d6; sem fundamentos, o golpe não acontece. A contagem vem da lista de fundamentos da técnica.","legado":"se @USUARIO.qtd_fundamentos > 0 entao subtrair @USUARIO.qtd_fundamentos * 1d6 em @ALVO.vida","aliases":"qtd_fundamentos_tecnica"},{"id":"245","origem":"qtd_habilidades_especializacao","modelo":"quantidade habilidades especializacao","formula":"se @USUARIO.quantidade habilidades especializacao >= 3 entao somar 2 em @USUARIO.pericia oficio1","explicacao":"Um especialista recebe +2 em Ofício 1 quando já escolheu pelo menos três habilidades de especialização. Com duas, o bônus não entra; com três, entra. A chave conta as escolhas e não depende de quais habilidades específicas foram selecionadas.","legado":"se @USUARIO.qtd_habilidades_especializacao >= 3 entao somar 2 em @USUARIO.pericia_oficio1","aliases":"qtd_habilidades_spec"},{"id":"246","origem":"qtd_inimigos_adjacentes","modelo":"quantidade inimigos adjacentes","formula":"subtrair @USUARIO.quantidade inimigos adjacentes * 6 em @ALVO.vida","explicacao":"Causa 6 pontos de dano por inimigo adjacente ao usuário. Com 3 inimigos adjacentes, o resultado é 18 de dano.","legado":"subtrair @USUARIO.qtd_inimigos_adjacentes * 6 em @ALVO.vida","aliases":"qtd_inimigos_engajados"},{"id":"247","origem":"qtd_inimigos_proximos","modelo":"quantidade inimigos proximos","formula":"se @USUARIO.quantidade inimigos proximos >= 4 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma explosão de cerco se fortalece quando quatro ou mais inimigos estão dentro de 6 m do usuário. Com três, aplica o dano normal; com quatro, acrescenta 1d8. Essa contagem mede proximidade, mesmo que os inimigos não estejam adjacentes.","legado":"se @USUARIO.qtd_inimigos_proximos >= 4 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"248","origem":"qtd_itens_equipados","modelo":"quantidade itens equipados","formula":"se @USUARIO.quantidade itens equipados >= 5 entao subtrair 1 em @USUARIO.defesa","explicacao":"Uma armadura improvisada fica desajeitada se cinco ou mais itens ocupam slots ao mesmo tempo e impõe -1 de Defesa. Com quatro itens equipados, não há penalidade. A chave conta equipamentos ativos, não tudo que está guardado na mochila.","legado":"se @USUARIO.qtd_itens_equipados >= 5 entao subtrair 1 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"249","origem":"qtd_itens_inventario","modelo":"quantidade itens inventario","formula":"se @USUARIO.quantidade itens inventario > 20 entao subtrair 3 em @USUARIO.contador metros_taticos","explicacao":"Carregar mais de 20 itens aplica uma penalidade de 3 m ao saldo de metros_taticos nesta regra de sobrecarga narrativa. Com exatamente 20 itens não penaliza; ao chegar a 21, o peso extra começa a atrapalhar. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.qtd_itens_inventario > 20 entao subtrair 3 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"250","origem":"qtd_participantes_combate","modelo":"quantidade participantes combate","formula":"se @USUARIO.quantidade participantes combate >= 5 entao somar 2 em @USUARIO.defesa","explicacao":"A formação fecha fileiras quando há pelo menos cinco participantes na ordem de iniciativa. Com quatro combatentes, não recebe o bônus; com cinco ou mais, ganha +2 de Defesa para aguentar a luta em grupo. A contagem inclui todas as entradas da ordem.","legado":"se @USUARIO.qtd_participantes_combate >= 5 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"251","origem":"qtd_sustentados","modelo":"quantidade buffs sustentados","formula":"se @USUARIO.quantidade buffs sustentados >= 3 entao subtrair 2 em @USUARIO.pe","explicacao":"Manter três ou mais buffs sustentados exige 2 PE adicionais neste exemplo. Com dois efeitos, o custo não dispara; ao ativar o terceiro, passa a valer. Use a contagem atual para custos que aumentam conforme os efeitos simultâneos.","legado":"se @USUARIO.qtd_sustentados >= 3 entao subtrair 2 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"252","origem":"qtd_talentos","modelo":"quantidade talentos","formula":"se @USUARIO.quantidade talentos >= 5 entao somar 2 em @USUARIO.defesa","explicacao":"Uma recompensa de veterano concede +2 de Defesa quando a ficha possui cinco ou mais talentos. Com quatro talentos, a condição falha; ao adquirir o quinto, o bônus passa a valer. A contagem permite escalonar efeitos conforme a construção do personagem.","legado":"se @USUARIO.qtd_talentos >= 5 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"253","origem":"qtd_talentos_combate","modelo":"quantidade talentos combate","formula":"subtrair 1d8 + @USUARIO.quantidade talentos combate em @ALVO.vida","explicacao":"Uma técnica de veterano soma à rolagem o total de talentos de combate da ficha. Com dois talentos e resultado 5 no d8, causa 7; com quatro, causa 9. O exemplo usa a quantidade do grupo de combate, não o total de todos os talentos.","legado":"subtrair 1d8 + @USUARIO.qtd_talentos_combate em @ALVO.vida","aliases":"nenhum listado"},{"id":"254","origem":"qtd_vantagens","modelo":"quantidade vantagens","formula":"se @USUARIO.quantidade vantagens >= 2 entao somar 2 em @USUARIO.acerto","explicacao":"Uma mira preparada com dois ou mais modificadores de Vantagem concede +2 de Acerto adicional nesta regra. Um modificador não basta; dois ou mais ativam. A contagem permite criar escalonamento quando várias fontes diferentes favorecem o mesmo teste.","legado":"se @USUARIO.qtd_vantagens >= 2 entao somar 2 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"255","origem":"reacao_disponivel","modelo":"reacao disponivel","formula":"se @USUARIO.reacao disponivel > 0 entao subtrair 1 em @USUARIO.reacao restantes, somar 3 em @USUARIO.defesa","explicacao":"A defesa reativa exige uma reação disponível. Consome uma reação restante e acrescenta 3 à Defesa. Configure o gatilho de ataque declarado e a remoção desse bônus após o ataque; a fórmula sozinha não define sua duração.","legado":"se @USUARIO.reacao_disponivel > 0 entao subtrair 1 em @USUARIO.reacao_disponivel, somar 3 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"256","origem":"reacao_usada","modelo":"reacao usada","formula":"se @USUARIO.reacao usada = 0 entao subtrair 1 em @USUARIO.reacao restantes, somar 1 em @USUARIO.vida temporaria","explicacao":"A postura exige que nenhuma reação tenha sido usada, consome uma reação restante e concede 1 PV temporário. A consulta usada não é um marcador gravável. Configure o limite e a renovação de reações no combate.","legado":"se @USUARIO.reacao_usada = 0 entao somar 1 em @USUARIO.reacao_usada, somar 1 em @USUARIO.vida_temp","aliases":"reacao_usada_nesta_rodada"},{"id":"257","origem":"reacoes_max","modelo":"maximo reacao","formula":"definir @USUARIO.maximo reacao em @USUARIO.restante reacao","explicacao":"No começo da rodada, copia o máximo de reações para o saldo disponível. Um talento que dá 2 reações deixa 2 para gastar; uma ficha com máximo 1 começa com 1. Ao consumir uma reação, reduza o saldo, não o máximo.","legado":"definir @USUARIO.reacoes_max em @USUARIO.reacoes_restantes","aliases":"nenhum listado"},{"id":"258","origem":"reacoes_restantes","modelo":"restante reacao","formula":"se @USUARIO.restante reacao > 0 entao subtrair 1 em @USUARIO.restante reacao, somar 1d8 em @USUARIO.vida temporaria","explicacao":"Ao aparar um golpe, o personagem gasta uma reação disponível e recebe 1d8 PV temporários para absorver o impacto. Com uma reação restante, consome-a; com zero, não pode aparar. O saldo diminui, mas o limite máximo de reações da ficha permanece.","legado":"se @USUARIO.reacoes_restantes > 0 entao subtrair 1 em @USUARIO.reacoes_restantes, somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"259","origem":"reacoes_usadas","modelo":"quantidade reacoes usadas","formula":"se @USUARIO.quantidade reacoes usadas >= 2 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma técnica de contra-ataque causa 1d8 ao agressor se o personagem já gastou pelo menos duas reações nesta rodada, representando uma defesa treinada que se converte em golpe. Com zero ou uma reação usada, não dispara; com duas ou mais, o requisito é atendido. A fórmula consulta o contador e não subtrai uma terceira reação restante.","legado":"se @USUARIO.reacoes_usadas >= 2 entao subtrair 1d8 em @ALVO.vida","aliases":"reacoes_usadas_nesta_rodada"},{"id":"260","origem":"reducao_dano_alma","modelo":"reducao dano alma","formula":"subtrair max(1, 2d8 - @ALVO.reducao dano alma) em @ALVO.vida","explicacao":"Um ataque de Alma causa 2d8 e desconta a redução específica do alvo, mantendo pelo menos 1 ponto de dano. Com dados 10 e RD de Alma 4, causa 6; se a redução exceder o total, o mínimo preserva 1. Outros tipos de dano não precisam usar esse valor.","legado":"subtrair max(1, 2d8 - @ALVO.reducao_dano_alma) em @ALVO.vida","aliases":"rd_alma"},{"id":"261","origem":"reflexos","modelo":"reflexos","formula":"se @ALVO.reflexos >= @CENA.dificuldade entao subtrair 1d6 em @ALVO.vida","explicacao":"Quando uma explosão tem CD 14, Reflexos 14 permite ao personagem esquivar parcialmente e sofrer só 1d6 neste ramo de sucesso. Com 13, falha na comparação e a resolução pode aplicar o dano maior. O sinal >= inclui o empate com a CD.","legado":"se @ALVO.reflexos >= @CENA.dificuldade entao subtrair 1d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"262","origem":"reserva_pe","modelo":"reserva pe","formula":"se @USUARIO.reserva pe >= 3 entao subtrair 3 em @USUARIO.reserva pe, somar 3 em @USUARIO.pe","explicacao":"O personagem converte 3 pontos guardados na reserva em PE utilizável. A regra exige saldo suficiente; com 2 na reserva, não executa, e com 5, transfere 3 e deixa 2 armazenados. Use quando uma habilidade transforma energia poupada em energia imediata.","legado":"se @USUARIO.reserva_pe >= 3 entao subtrair 3 em @USUARIO.reserva_pe, somar 3 em @USUARIO.pe","aliases":"reserva_pe_atual"},{"id":"263","origem":"reserva_pe_disponivel","modelo":"reserva pe disponivel","formula":"se @USUARIO.reserva pe disponivel > 0 entao subtrair 1 em @USUARIO.reserva pe, somar 1 em @USUARIO.pe","explicacao":"Esta chave funciona como uma verificação simples: vale 1 quando existe energia armazenada e 0 quando a reserva está vazia. O exemplo libera uma conversão de 1 PE somente no primeiro caso; com 4 na reserva, usa 1 e deixa 3.","legado":"se @USUARIO.reserva_pe_disponivel > 0 entao subtrair 1 em @USUARIO.reserva_pe, somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"264","origem":"reserva_pe_recuperavel","modelo":"recuperavel reserva pe","formula":"subtrair @USUARIO.recuperavel reserva pe em @USUARIO.reserva pe, somar @USUARIO.recuperavel reserva pe em @USUARIO.pe","explicacao":"Transfere para o PE atual exatamente a parcela da reserva que cabe antes de atingir o máximo. Se há 8 na reserva, mas só cabem 3 PE, transfere 3 e preserva 5; se cabem todos os 8, transfere os 8. Isso evita exceder a capacidade.","legado":"subtrair @USUARIO.reserva_pe_recuperavel em @USUARIO.reserva_pe, somar @USUARIO.reserva_pe_recuperavel em @USUARIO.pe","aliases":"nenhum listado"},{"id":"265","origem":"resistencia","modelo":"reducao dano","formula":"subtrair max(1, 2d8 - @ALVO.reducao dano) em @ALVO.vida","explicacao":"Uma armadura reduz um impacto de 2d8 pela RD do alvo, mas o golpe ainda causa pelo menos 1 ponto. Se os dados somarem 9 e a Resistência for 4, entram 5 de dano; se a RD for 12, o mínimo mantém 1. Isso demonstra redução numérica sem fixar uma RD específica.","legado":"subtrair max(1, 2d8 - @ALVO.resistencia) em @ALVO.vida","aliases":"nenhum listado"},{"id":"266","origem":"rodada","modelo":"rodada","formula":"quando @CENA.rodada = 3 -> subtrair 2d6 em @ALVO.vida","explicacao":"Uma armadilha programada dispara na terceira rodada de combate e causa 2d6 ao alvo. Na rodada 2 não ocorre; quando o contador chega a 3, o gatilho é satisfeito. rodadas_em_combate é um alias aceito para o estado da rodada.","legado":"quando @CENA.rodada = 3 -> subtrair 2d6 em @ALVO.vida","aliases":"rodadas_em_combate"},{"id":"267","origem":"sab","modelo":"sab","formula":"se @USUARIO.sab >= 4 entao somar 2 em @USUARIO.pericia percepcao","explicacao":"Uma bênção de vigilância concede +2 em Percepção somente a quem tem Sabedoria 4 ou maior. Com Sabedoria 3, nada acontece; com Sabedoria 4, aplica o bônus. A condição pode ser reaproveitada em efeitos diferentes que dependam do mesmo atributo.","legado":"se @USUARIO.sab >= 4 entao somar 2 em @USUARIO.pericia_percepcao","aliases":"sabedoria"},{"id":"268","origem":"sacrificio_pct","modelo":"percentual sacrificio","formula":"se @USUARIO.percentual sacrificio >= 25 entao subtrair 3d8 em @ALVO.vida","explicacao":"Um pacto sombrio libera 3d8 de dano quando o sacrifício acumulado equivale a pelo menos 25% da Vida Máxima. Com máximo 40, 10 PV sacrificados atingem exatamente 25%; 9 ficam abaixo do limite. O percentual informado vai de 0 a 100.","legado":"se @USUARIO.sacrificio_pct >= 25 entao subtrair 3d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"269","origem":"saldo_<moeda>","modelo":"saldo <moeda>","formula":"se @USUARIO.saldo yen >= 500 entao somar 2d8 em @ALVO.vida","explicacao":"Troque <moeda> pelo identificador real; neste caso, yen. Uma clínica aceita 500 ienes para aplicar um tratamento que restaura 2d8 PV. Abaixo de 500, a fórmula não libera o tratamento; a moeda padrão da ficha pode ser outra.","legado":"se @USUARIO.saldo_yen >= 500 entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"270","origem":"saldo_padrao","modelo":"saldo padrao","formula":"se @USUARIO.saldo padrao >= 100 entao somar 1 em @USUARIO.sorte","explicacao":"A guilda concede um favor a quem mantém ao menos 100 unidades da moeda padrão. O personagem ganha 1 uso de Sorte com saldo 100; com 99, não. Este valor soma a moeda padrão de todas as carteiras, inclusive compartilhadas.","legado":"se @USUARIO.saldo_padrao >= 100 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"271","origem":"saldo_pessoal","modelo":"saldo pessoal","formula":"se @USUARIO.saldo pessoal >= 50 entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Uma reserva de emergência na carteira pessoal compra um talismã que concede 1d8 PV temporários quando há pelo menos 50 moedas próprias. O saldo do grupo não conta: somente a carteira pessoal pode ativar esta compra.","legado":"se @USUARIO.saldo_pessoal >= 50 entao somar 1d8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"272","origem":"saldo_total","modelo":"saldo total","formula":"se @USUARIO.saldo total >= 1000 entao somar 2 em @USUARIO.pericia persuasao","explicacao":"Um nobre que pode demonstrar pelo menos 1.000 moedas em todas as carteiras recebe +2 em Persuasão ao negociar com o conselho. Com saldo 950, não convence pela riqueza; com 1.000 ou mais, o bônus entra. A chave soma moedas de todas as carteiras.","legado":"se @USUARIO.saldo_total >= 1000 entao somar 2 em @USUARIO.pericia_persuasao","aliases":"nenhum listado"},{"id":"273","origem":"segundos_restantes_turno","modelo":"segundos restante turno","formula":"se @USUARIO.segundos restante turno > 0 e @USUARIO.segundos restante turno <= 5 entao somar 2 em @USUARIO.defesa","explicacao":"Nos últimos cinco segundos ainda disponíveis, o personagem ergue a guarda e ganha +2 de Defesa. Com 8 segundos, não ativa; com 5, 3 ou 1, ativa. Em 0, o turno já terminou.","legado":"se @USUARIO.segundos_restantes_turno > 0 e @USUARIO.segundos_restantes_turno <= 5 entao somar 2 em @USUARIO.defesa","aliases":"turno_segundos_restantes"},{"id":"274","origem":"slots_concentracao_livres","modelo":"livre concentracao","formula":"se @USUARIO.livre concentracao > 0 entao subtrair 2 em @USUARIO.pe","explicacao":"Uma nova magia de concentração só pode ser iniciada se ainda houver ao menos um espaço livre. Com máximo 3 e dois efeitos ativos, resta 1 e o custo de 2 PE é pago; com zero espaços, a fórmula não inicia outro efeito.","legado":"se @USUARIO.slots_concentracao_livres > 0 entao subtrair 2 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"275","origem":"slots_descanso_curto","modelo":"dado_vida","formula":"se @USUARIO.dado_vida > 0 entao subtrair 1 em @USUARIO.dado_vida, somar 1d8 + @USUARIO.atributo con em @USUARIO.vida","explicacao":"Durante um descanso curto, gasta um Dado de Vida disponível e cura 1d8 mais Constituição. Com 2 dados restantes, usa um e deixa 1; com zero, não pode rolar outro dado. Este card representa o estoque atual de dados de vida.","legado":"se @USUARIO.slots_descanso_curto > 0 entao subtrair 1 em @USUARIO.slots_descanso_curto, somar 1d8 + @USUARIO.con em @USUARIO.vida","aliases":"nenhum listado"},{"id":"276","origem":"slots_descanso_curto_max","modelo":"maximo dado_vida","formula":"somar @USUARIO.maximo dado_vida - @USUARIO.dado_vida em @USUARIO.dado_vida","explicacao":"Após um descanso longo, repõe os Dados de Vida gastos até o total máximo. Se o limite é 8 e restam 3, acrescenta 5; se já há 8, acrescenta zero. A chave acompanha o nível e o máximo da ficha.","legado":"somar @USUARIO.slots_descanso_curto_max - @USUARIO.slots_descanso_curto em @USUARIO.slots_descanso_curto","aliases":"nenhum listado"},{"id":"277","origem":"slots_descanso_curto_pct","modelo":"percentual dado_vida","formula":"se @USUARIO.percentual dado_vida <= 25 entao somar 1d8 em @USUARIO.vida","explicacao":"Uma característica de descanso recupera 1d8 PV quando restam 25% ou menos dos Dados de Vida. Com 8 dados máximos, dois restantes são 25% e ativam; três restantes são 37,5% e não. O valor percentual é expresso de 0 a 100.","legado":"se @USUARIO.slots_descanso_curto_pct <= 25 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"278","origem":"slots_sustentado_livres","modelo":"livre sustentacao","formula":"se @USUARIO.livre sustentacao > 0 entao somar 1d8 em @ALVO.vida temporaria","explicacao":"Uma nova proteção sustentada só pode ser criada se ainda houver um espaço livre; ao iniciar, concede 1d8 PV temporários ao aliado. Com limite 4 e três efeitos ativos, resta um espaço; com quatro ativos, a fórmula não libera outra proteção.","legado":"se @USUARIO.slots_sustentado_livres > 0 entao somar 1d8 em @ALVO.vida_temp","aliases":"nenhum listado"},{"id":"279","origem":"sobrecarregado","modelo":"sobrecarregado","formula":"se @USUARIO.sobrecarregado > 0 entao subtrair 3 em @USUARIO.contador metros_taticos","explicacao":"No início do deslocamento, uma penalidade de carga remove 3 m do contador metros_taticos se os espaços ocupados superarem o máximo da ficha. Com a flag em 0, o personagem mantém a velocidade normal. A chave traduz sobrecarga em um ajuste explícito. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"se @USUARIO.sobrecarregado > 0 entao subtrair 3 em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"280","origem":"sorte","modelo":"sorte","formula":"se @USUARIO.sorte > 0 entao subtrair 1 em @USUARIO.sorte, subtrair 1d10 em @ALVO.vida","explicacao":"O personagem pode gastar uma utilização de Sorte para fortalecer um ataque com 1d10 extra. A ação só segue se ainda houver pelo menos um uso; com zero, não consome recurso nem aplica o dano. Assim, a mesma chave serve para limitar qualquer efeito por usos restantes.","legado":"se @USUARIO.sorte > 0 entao subtrair 1 em @USUARIO.sorte, subtrair 1d10 em @ALVO.vida","aliases":"sorte_atual"},{"id":"281","origem":"sorte_max","modelo":"maximo sorte","formula":"somar @USUARIO.maximo sorte - @USUARIO.sorte em @USUARIO.sorte","explicacao":"No começo do dia, esta fórmula restaura os usos gastos até o limite diário. Se o máximo for 3 e restar 1, devolve 2; se já houver 3, devolve zero. O exemplo lê o máximo e altera o estoque atual, sem codificar um limite fixo.","legado":"somar @USUARIO.sorte_max - @USUARIO.sorte em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"282","origem":"sou_proximo_no_turno","modelo":"usuario turno proximo","formula":"se @USUARIO.usuario turno proximo > 0 entao somar 1d8 em @USUARIO.vida temporaria","explicacao":"Ao saber que será o próximo a agir, o personagem recebe 1d8 PV temporários para entrar na linha de frente. O marcador vale 1 somente quando sua vez vem imediatamente após a atual.","legado":"se @USUARIO.sou_proximo_no_turno > 0 entao somar 1d8 em @USUARIO.vida_temp","aliases":"proximo_no_turno"},{"id":"283","origem":"sou_ultimo_no_turno","modelo":"usuario turno ultimo","formula":"se @USUARIO.usuario turno ultimo > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma técnica de encerramento causa 1d8 extra quando o personagem ocupa a última posição da iniciativa. Se estiver em qualquer posição anterior, o bônus não acontece.","legado":"se @USUARIO.sou_ultimo_no_turno > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"ultimo_no_turno"},{"id":"284","origem":"sozinho","modelo":"sozinho","formula":"se @USUARIO.sozinho > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Um talento de lobo solitário concede +2 de Defesa se não houver nenhum aliado a até 6 m. Com um aliado dentro do raio, a chave vale 0; a distância é maior que adjacência e pode incluir companheiros que não estejam ao lado.","legado":"se @USUARIO.sozinho > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"285","origem":"suporte_lv2_unlocked","modelo":"suporte nivel 2","formula":"se @USUARIO.suporte nivel 2 > 0 entao somar 2d8 em @ALVO.vida","explicacao":"O suporte avançado só libera esta cura de 2d8 quando Adepto de Medicina desbloqueou o nível 2. Com a chave em 1, cura o aliado; com 0, não executa a opção avançada. Isso permite manter a habilidade no mesmo construtor e condicionar a parte aprimorada.","legado":"se @USUARIO.suporte_lv2_unlocked > 0 entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"286","origem":"sustentados_maximos","modelo":"sustentacao max","formula":"se @USUARIO.sustentacao max >= 3 entao somar 1d6 em @USUARIO.vida","explicacao":"Uma bênção de estabilidade concede 1d6 PV a quem consegue manter três ou mais feitiços sustentados. O limite 2 não basta; limites 3 e 4 ativam a regra. Este exemplo usa a capacidade do personagem como requisito narrativo para outra habilidade.","legado":"se @USUARIO.sustentados_maximos >= 3 entao somar 1d6 em @USUARIO.vida","aliases":"max_sustentados"},{"id":"287","origem":"swaps_armas_neste_turno","modelo":"quantidade trocas_arma turno","formula":"se @USUARIO.quantidade trocas_arma turno >= 2 entao subtrair 1 em @USUARIO.ataques restantes","explicacao":"Uma regra de combate rápido penaliza a segunda troca de empunhadura no mesmo turno, consumindo um ataque disponível. A primeira troca não ativa; quando o contador chega a 2, o custo entra. O número acompanha as trocas já realizadas.","legado":"se @USUARIO.swaps_armas_neste_turno >= 2 entao subtrair 1 em @USUARIO.ataques_restantes","aliases":"nenhum listado"},{"id":"288","origem":"tamanho","modelo":"tamanho","formula":"se @ALVO.tamanho >= 3 entao subtrair 2d8 em @ALVO.vida","explicacao":"Uma armadilha de queda causa 2d8 extras a criaturas Grandes ou maiores: tamanho 3 atende ao limite, enquanto Pequeno (1) e Médio (2) não. A chave permite ajustar efeitos pelo porte da criatura, sem criar uma regra separada para cada espécie.","legado":"se @ALVO.tamanho >= 3 entao subtrair 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"289","origem":"tem_aptidao_<id>","modelo":"tem aptidao <id>","formula":"se @USUARIO.tem aptidao aura_protetora > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Substitua <id> pelo identificador da aptidão que deseja testar. Neste caso, aura_protetora concede +2 de Defesa apenas a quem a adquiriu. A condição vale 1 quando está presente e 0 quando ausente.","legado":"se @USUARIO.tem_aptidao_aura_protetora > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"290","origem":"tem_buff_<nome>","modelo":"tem buff <nome>","formula":"se @USUARIO.tem buff armadura_arcana > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Substitua <nome> pelo nome do buff normalizado; neste exemplo, armadura_arcana. Enquanto houver um buff ativo com esse nome, a fórmula concede +2 de Defesa. Quando o buff termina ou o nome não coincide, o marcador vale 0.","legado":"se @USUARIO.tem_buff_armadura_arcana > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"291","origem":"tem_carteira_pessoal","modelo":"tem carteira pessoal","formula":"se @USUARIO.tem carteira pessoal > 0 entao somar 1 em @USUARIO.sorte","explicacao":"Uma vantagem de contrato exige uma carteira pessoal ativa e concede 1 uso de Sorte ao proprietário. O marcador 1 confirma que a carteira existe; com 0, o benefício não está disponível. Isso separa posse de carteira de seu saldo atual.","legado":"se @USUARIO.tem_carteira_pessoal > 0 entao somar 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"292","origem":"tem_condicao_<id>","modelo":"tem condicao <id>","formula":"se @ALVO.tem condicao atordoado > 0 entao subtrair 2d8 + @USUARIO.treino em @ALVO.vida","explicacao":"Substitua <id> pelo identificador da condição; aqui, a técnica contra Atordoado soma 2d8 mais Treinamento ao golpe. Se o alvo está Atordoado, aplica; caso contrário, não. O exemplo demonstra como trocar a condição sem criar uma key exclusiva para cada habilidade.","legado":"se @ALVO.tem_condicao_atordoado > 0 entao subtrair 2d8 + @USUARIO.treino em @ALVO.vida","aliases":"nenhum listado"},{"id":"293","origem":"tem_desvantagem","modelo":"tem desvantagem","formula":"se @USUARIO.tem desvantagem > 0 entao subtrair 1 em @USUARIO.sorte","explicacao":"Uma técnica de risco custa 1 uso de Sorte se o personagem tentar executá-la enquanto houver ao menos um modificador de Desvantagem ativo. Sem desvantagem, não há esse custo adicional. O marcador não substitui a rolagem com desvantagem feita pelo motor.","legado":"se @USUARIO.tem_desvantagem > 0 entao subtrair 1 em @USUARIO.sorte","aliases":"nenhum listado"},{"id":"294","origem":"tem_feitico_<id>","modelo":"tem feitico <id>","formula":"se @USUARIO.tem feitico bola_de_fogo > 0 entao subtrair 3d6 em @ALVO.vida","explicacao":"Troque <id> pelo identificador exato do feitiço; aqui, bola_de_fogo. Se esse feitiço estiver no grimório, a chave dinâmica vale 1 e a explosão causa 3d6; se o ID não corresponder a um feitiço conhecido, vale 0 e não libera o efeito.","legado":"se @USUARIO.tem_feitico_bola_de_fogo > 0 entao subtrair 3d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"295","origem":"tem_feitico_pronto","modelo":"tem feitico pronto","formula":"se @USUARIO.tem feitico pronto > 0 entao somar 1d8 em @ALVO.vida","explicacao":"O personagem pode usar o impulso de conjuração se tiver qualquer feitiço marcado como preparado. A chave vale 1 quando existe ao menos um e 0 quando todos estão indisponíveis; nesse exemplo, o impulso acrescenta 1d8 ao efeito atual.","legado":"se @USUARIO.tem_feitico_pronto > 0 entao somar 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"296","origem":"tem_habilidade_<id>","modelo":"tem habilidade <id>","formula":"se @USUARIO.tem habilidade mestre_das_laminas > 0 entao subtrair 1d10 em @ALVO.vida","explicacao":"Use o identificador real da habilidade no lugar de <id>; o exemplo testa mestre_das_laminas. Se a ficha tem a habilidade, o golpe recebe 1d10; sem ela, não. Isso permite condicionar efeitos a uma escolha individual da especialização.","legado":"se @USUARIO.tem_habilidade_mestre_das_laminas > 0 entao subtrair 1d10 em @ALVO.vida","aliases":"nenhum listado"},{"id":"297","origem":"tem_item_<id>","modelo":"tem item <id>","formula":"se @USUARIO.tem item pocao_de_cura > 0 entao somar 2d8 em @USUARIO.vida","explicacao":"Troque <id> pelo identificador exato do item; aqui, pocao_de_cura. Se a poção está no inventário, a fórmula restaura 2d8 PV; se foi consumida, vendida ou não existe, o efeito não é liberado.","legado":"se @USUARIO.tem_item_pocao_de_cura > 0 entao somar 2d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"298","origem":"tem_moeda_<moeda>","modelo":"tem moeda <moeda>","formula":"se @USUARIO.tem moeda yen > 0 entao somar 1 em @USUARIO.pe","explicacao":"Substitua <moeda> pela moeda a verificar. Com yen, a chave vale 1 se o personagem possui qualquer saldo positivo em ienes, mesmo que seja pouco; então recebe 1 PE de um selo comprado. Saldo zero não ativa a regra.","legado":"se @USUARIO.tem_moeda_yen > 0 entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"299","origem":"tem_talento_<id>","modelo":"tem talento <id>","formula":"se @USUARIO.tem talento especialista_escudos > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Troque <id> pelo identificador exato do talento; especialista_escudos é o exemplo usado aqui. Se a ficha possui esse talento, recebe +2 de Defesa; se não possui, o efeito não acontece. A chave verifica um talento específico, não a quantidade total.","legado":"se @USUARIO.tem_talento_especialista_escudos > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"300","origem":"tem_tecnica","modelo":"tem tecnica","formula":"se @USUARIO.tem tecnica > 0 entao subtrair 2d8 em @ALVO.vida","explicacao":"O golpe especial só é liberado se o personagem tiver uma técnica amaldiçoada definida. Com a técnica preenchida, causa 2d8; sem ela, o marcador vale 0 e a fórmula não executa o ataque.","legado":"se @USUARIO.tem_tecnica > 0 entao subtrair 2d8 em @ALVO.vida","aliases":"tecnica_amaldicoada_definida"},{"id":"301","origem":"tem_ultimo_feitico","modelo":"tem feitico anterior","formula":"se @USUARIO.tem feitico anterior > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma técnica de combinação acrescenta 1d8 ao ataque se o personagem já tiver um último feitiço registrado. Antes de qualquer conjuração a chave vale 0 e o bônus não ocorre; depois de usar um feitiço, vale 1. Ela verifica a existência do registro, não qual feitiço foi usado.","legado":"se @USUARIO.tem_ultimo_feitico > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"302","origem":"tem_vantagem","modelo":"tem vantagem","formula":"se @USUARIO.tem vantagem > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Um disparo aproveita um modificador de Vantagem ativo para acrescentar 1d8 ao dano. A chave vale 1 se existe ao menos um modificador; sem nenhum, o dano extra não entra. A rolagem com vantagem em si é resolvida pelo motor de ataque.","legado":"se @USUARIO.tem_vantagem > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"303","origem":"treino","modelo":"treino","formula":"subtrair 1d8 + @USUARIO.treino em @ALVO.vida","explicacao":"Um golpe de classe treinada soma o Bônus de Treinamento ao dado de dano. Se o treino vale 3 e o d8 mostra 6, o alvo recebe 9 de dano. A fórmula cresce conforme a progressão do personagem sem exigir uma versão diferente da habilidade por nível.","legado":"subtrair 1d8 + @USUARIO.treino em @ALVO.vida","aliases":"bonus_treinamento, bonusdetreinamento, bonustreinamento, treinamento"},{"id":"304","origem":"turno_cronometro_ativo","modelo":"cronometro ativo","formula":"se @USUARIO.cronometro ativo > 0 entao subtrair 1 em @USUARIO.pe","explicacao":"Enquanto o cronômetro de turnos estiver ligado, uma armadura temporal consome 1 PE no pulso de manutenção. Se o cronômetro estiver desligado, não há cobrança. Associe a fórmula ao pulso de manutenção, para cobrar uma vez por intervalo definido.","legado":"se @USUARIO.turno_cronometro_ativo > 0 entao subtrair 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"305","origem":"turno_pausado","modelo":"turno pausado","formula":"se @USUARIO.turno pausado > 0 entao somar 1 em @USUARIO.pe","explicacao":"Quando o Mestre pausa o cronômetro, um cristal de foco devolve 1 PE ao conjurador. A chave vale 1 durante a pausa e 0 enquanto o relógio corre; execute no evento de pausa uma única vez, evitando repetir o reembolso enquanto a pausa durar.","legado":"se @USUARIO.turno_pausado > 0 entao somar 1 em @USUARIO.pe","aliases":"nenhum listado"},{"id":"306","origem":"turnos_ate_meu_turno","modelo":"turnos ate minha_vez","formula":"se @USUARIO.em_combate > 0 e @USUARIO.turnos ate minha_vez <= 1 entao somar 2 em @USUARIO.defesa","explicacao":"O personagem ergue a guarda quando sua vez chegou ou será a próxima: 0 indica a vez atual e 1 indica a próxima posição. Se faltam 2 ou mais turnos, não ganha o bônus. Fora de combate, a condição externa impede a ativação.","legado":"se @USUARIO.em_combate > 0 e @USUARIO.turnos_ate_meu_turno <= 1 entao somar 2 em @USUARIO.defesa","aliases":"turnos_ate_meu"},{"id":"307","origem":"ultimo_ataque_acertou","modelo":"ataque anterior acertou","formula":"se @USUARIO.ataque anterior acertou > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"Uma técnica de combo libera um golpe de continuação se o último ataque acertou. Depois de um acerto, causa 1d8 adicional; após um erro, não. A marca do resultado anterior evita calcular novamente o teste do ataque.","legado":"se @USUARIO.ultimo_ataque_acertou > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"308","origem":"ultimo_ataque_errou","modelo":"ataque anterior errou","formula":"se @USUARIO.ataque anterior errou > 0 entao somar 1 em @USUARIO.acerto","explicacao":"Uma habilidade de correção concede +1 de Acerto ao próximo golpe se o ataque anterior errou. Se o último resultado foi acerto, a compensação não ativa. A chave permite criar efeitos que respondem ao resultado recém-resolvido.","legado":"se @USUARIO.ultimo_ataque_errou > 0 entao somar 1 em @USUARIO.acerto","aliases":"nenhum listado"},{"id":"309","origem":"ultimo_dano_recebido","modelo":"ultimo dano recebido","formula":"subtrair floor(@USUARIO.ultimo dano recebido / 2) em @ALVO.vida","explicacao":"Um contra-ataque devolve metade do último dano sofrido, arredondada para baixo. Se o usuário recebeu 13 de dano, o atacante perde 6 PV; se recebeu 8, perde 4. Use o alvo como a criatura que causou o golpe.","legado":"subtrair floor(@USUARIO.ultimo_dano_recebido / 2) em @ALVO.vida","aliases":"nenhum listado"},{"id":"310","origem":"usou_corrida","modelo":"usou corrida","formula":"se @USUARIO.usou corrida > 0 entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma manobra de impacto só pode ser usada depois de gastar a ação de Corrida neste turno; quando a flag vale 1, causa 2d6. Se o personagem apenas caminhou, não recebe o dano de investida.","legado":"se @USUARIO.usou_corrida > 0 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"311","origem":"vantagem_proxima_pericia","modelo":"vantagem proxima pericia","formula":"se @USUARIO.vantagem proxima pericia > 0 entao somar 2 em @USUARIO.pericia investigacao","explicacao":"Ao examinar uma cena, um modificador de Vantagem reservado para a próxima perícia concede +2 em Investigação. A vantagem precisa afetar uma perícia; um bônus para ataque não ativa esse exemplo.","legado":"se @USUARIO.vantagem_proxima_pericia > 0 entao somar 2 em @USUARIO.pericia_investigacao","aliases":"nenhum listado"},{"id":"312","origem":"vantagem_proximo_ataque","modelo":"vantagem proximo ataque","formula":"se @USUARIO.vantagem proximo ataque > 0 entao subtrair 1d8 em @ALVO.vida","explicacao":"O próximo ataque recebe 1d8 adicional quando ao menos um modificador de Vantagem está marcado especificamente para ataques. Uma vantagem válida apenas para perícias ou TRs não ativa este efeito.","legado":"se @USUARIO.vantagem_proximo_ataque > 0 entao subtrair 1d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"313","origem":"vantagem_proximo_tr","modelo":"vantagem proximo tr","formula":"se @USUARIO.vantagem proximo tr > 0 entao somar 2 em @USUARIO.vontade","explicacao":"Antes de resistir a uma compulsão, a Vantagem marcada para o próximo TR concede +2 em Vontade nesta regra. Uma vantagem reservada para ataque não se aplica a este teste.","legado":"se @USUARIO.vantagem_proximo_tr > 0 entao somar 2 em @USUARIO.vontade","aliases":"nenhum listado"},{"id":"314","origem":"velocidade_atual","modelo":"movimento efetivo","formula":"somar @USUARIO.movimento efetivo em @USUARIO.contador metros_taticos","explicacao":"Ao usar uma ação de Corrida, acrescenta ao saldo de metros_taticos uma segunda parcela igual à velocidade efetiva. Se sobrecarga reduziu a velocidade para 6 m, acrescenta 6; sem sobrecarga, uma velocidade de 9 m acrescenta 9. Neste exemplo, metros_taticos é um contador de distância criado pela mesa. Inicialize-o antes da ação e vincule-o à regra de deslocamento personalizada; ele não altera automaticamente o orçamento do mapa.","legado":"somar @USUARIO.velocidade_atual em @USUARIO.movimento_restante","aliases":"nenhum listado"},{"id":"315","origem":"vendado","modelo":"vendado","formula":"se @USUARIO.vendado > 0 entao somar 2 em @USUARIO.pericia intuicao","explicacao":"Um personagem que luta vendado treina a leitura de movimentos pelo som e recebe +2 em Intuição enquanto a venda está equipada. Sem o item, o bônus não se aplica. O exemplo consulta o estado do slot, em vez de inferir isso pelo nome do equipamento.","legado":"se @USUARIO.vendado > 0 entao somar 2 em @USUARIO.pericia_intuicao","aliases":"nenhum listado"},{"id":"316","origem":"vida","modelo":"vida","formula":"quando @ALVO.vida <= 10 -> subtrair 2d8 em @ALVO.vida","explicacao":"Este gatilho observa a vida atual do alvo: ao chegar a 10 PV ou menos, dispara um golpe final de 2d8. Um alvo com 11 PV não satisfaz a condição; ao cair para 10, satisfaz. A comparação usa o valor atual, não o limite máximo.","legado":"quando @ALVO.vida <= 10 -> subtrair 2d8 em @ALVO.vida","aliases":"hp, pv, vida_atual"},{"id":"317","origem":"vida_faltante","modelo":"vida faltante","formula":"somar @ALVO.vida faltante em @ALVO.vida","explicacao":"Uma fonte de cura completa restaura exatamente o que falta até o máximo. Se o alvo tem 27 de 40 PV, acrescenta 13; com 9 de 40, acrescenta 31. O motor limita a cura ao teto da ficha.","legado":"somar @ALVO.vida_faltante em @ALVO.vida","aliases":"nenhum listado"},{"id":"318","origem":"vida_faltante_pct","modelo":"percentual vida faltante","formula":"se @ALVO.percentual vida faltante >= 75 entao somar 2d8 em @ALVO.vida","explicacao":"Uma poção de emergência fica reservada para quem perdeu pelo menos 75% da Vida Máxima. Em uma ficha com 40 PV máximos, 10 PV atuais significam 75% faltante e liberam 2d8; com 11 PV, o percentual faltante é menor.","legado":"se @ALVO.vida_faltante_pct >= 75 entao somar 2d8 em @ALVO.vida","aliases":"nenhum listado"},{"id":"319","origem":"vida_max","modelo":"vida max","formula":"somar floor(@ALVO.vida max * 0.2) em @ALVO.vida","explicacao":"Uma magia de recuperação restaura 20% da Vida Máxima do alvo, arredondando para baixo. Se o máximo for 37 PV, o cálculo dá 7 PV; com máximo 40, dá 8. A quantidade acompanha personagens de portes diferentes sem fixar uma cura única.","legado":"somar floor(@ALVO.vida_max * 0.2) em @ALVO.vida","aliases":"hp_max, pv_max"},{"id":"320","origem":"vida_pct","modelo":"percentual vida","formula":"se @ALVO.percentual vida <= 25 entao subtrair 2d6 em @ALVO.vida","explicacao":"Uma execução causa 2d6 adicionais apenas quando o alvo está com 25% ou menos da própria Vida Máxima. Um alvo de máximo 40 precisa estar com até 10 PV; alguém de máximo 80 precisa estar com até 20. Assim, o limite acompanha cada ficha.","legado":"se @ALVO.vida_pct <= 0.25 entao subtrair 2d6 em @ALVO.vida","aliases":"nenhum listado"},{"id":"321","origem":"vida_pct_abaixo_25","modelo":"vida ate 25%","formula":"se @ALVO.vida ate 25% > 0 entao subtrair 2d10 em @ALVO.vida","explicacao":"A técnica de execução acrescenta 2d10 quando o alvo está com no máximo um quarto da Vida Máxima. Com máximo 40, 10 PV ou menos ativa; com 11, não. criticamente_ferido é um alias válido para esse mesmo limite.","legado":"se @ALVO.vida_pct_abaixo_25 > 0 entao subtrair 2d10 em @ALVO.vida","aliases":"criticamente_ferido"},{"id":"322","origem":"vida_pct_abaixo_50","modelo":"vida ate 50%","formula":"se @ALVO.vida ate 50% > 0 entao somar 2d8 em @ALVO.vida","explicacao":"Um curandeiro usa esta checagem para priorizar aliados feridos: se o alvo está com metade ou menos da Vida Máxima, recupera 2d8 PV. Com máximo 40, 20 PV ou menos ativa; com 21, não. bloodied é um alias para a mesma chave.","legado":"se @ALVO.vida_pct_abaixo_50 > 0 entao somar 2d8 em @ALVO.vida","aliases":"bloodied"},{"id":"323","origem":"vida_temp","modelo":"vida temporaria","formula":"somar 12 em @USUARIO.vida temporaria","explicacao":"Uma barreira concede 12 pontos de vida temporários ao usuário. Esses pontos formam uma camada protetora consumida antes dos PV normais, então servem para escudos, bênçãos ou absorção temporária sem alterar Vida Máxima.","legado":"somar 12 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"324","origem":"vida_temp_max","modelo":"maximo vida temporaria","formula":"somar @USUARIO.maximo vida temporaria - @USUARIO.vida temporaria em @USUARIO.vida temporaria","explicacao":"Use para preencher exatamente a diferença entre os pontos temporários atuais e o teto configurado. Se o máximo for 15 e restarem 6, a fórmula acrescenta 9; se já houver 15, acrescenta zero. Isso permite criar uma ação de recomposição sem ultrapassar o limite.","legado":"somar @USUARIO.vida_temp_max - @USUARIO.vida_temp em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"325","origem":"vida_temp_pct","modelo":"percentual vida temporaria","formula":"se @USUARIO.percentual vida temporaria < 25 entao somar 8 em @USUARIO.vida temporaria","explicacao":"Uma armadura reativa concede 8 pontos temporários quando a proteção atual está abaixo de 25% do máximo. Se o máximo for 20 e restarem 4, o percentual é 20% e o escudo ativa; com 5 restantes, fica em 25% e a condição não ativa.","legado":"se @USUARIO.vida_temp_pct < 0.25 entao somar 8 em @USUARIO.vida_temp","aliases":"nenhum listado"},{"id":"326","origem":"vida_total","modelo":"vida total","formula":"se @USUARIO.vida total <= 15 entao somar 1d8 em @USUARIO.vida","explicacao":"A vida total soma PV atuais e pontos temporários. Com 11 PV e 3 temporários, o total é 14 e a cura de emergência de 1d8 é liberada; com 13 PV e 3 temporários, totaliza 16 e não dispara. Use quando a regra deve considerar a proteção inteira do personagem.","legado":"se @USUARIO.vida_total <= 15 entao somar 1d8 em @USUARIO.vida","aliases":"nenhum listado"},{"id":"327","origem":"vigor_maldito_bonus","modelo":"bonus vigor_maldito","formula":"somar 2d8 + @USUARIO.bonus vigor_maldito em @USUARIO.vida","explicacao":"Uma cura de Vigor Maldito restaura 2d8 PV e soma o bônus próprio desse talento. Se os dados totalizarem 9 e o bônus for 3, cura 12. O cálculo usa o bônus configurado para essa habilidade, sem aplicar esse valor a toda cura.","legado":"somar 2d8 + @USUARIO.vigor_maldito_bonus em @USUARIO.vida","aliases":"nenhum listado"},{"id":"328","origem":"vigor_maldito_disponivel","modelo":"vigor_maldito disponivel","formula":"se @USUARIO.vigor_maldito disponivel > 0 entao somar 2d8 + @USUARIO.bonus vigor_maldito em @ALVO.vida","explicacao":"Uma cura de Vigor Maldito só é liberada se houver ao menos um uso restante. Com a chave em 1, o aliado recebe 2d8 mais o bônus da habilidade; com 0, não tenta curar. O custo do uso deve ser consumido pela ação configurada.","legado":"se @USUARIO.vigor_maldito_disponivel > 0 entao somar 2d8 + @USUARIO.vigor_maldito_bonus em @ALVO.vida","aliases":"nenhum listado"},{"id":"329","origem":"vigor_maldito_max","modelo":"maximo vigor_maldito","formula":"definir @USUARIO.maximo vigor_maldito em @USUARIO.contador cargas_vigor","explicacao":"No início do dia, copia a capacidade de Vigor Maldito para o contador cargas_vigor desta regra personalizada. Com máximo 4, grava 4. O contador deve ser usado como custo pela ação correspondente; ele não modifica os usos nativos da habilidade.","legado":"somar @USUARIO.vigor_maldito_max - @USUARIO.vigor_maldito_usos em @USUARIO.vigor_maldito_usos","aliases":"nenhum listado"},{"id":"330","origem":"vigor_maldito_usos","modelo":"usos vigor_maldito","formula":"se @USUARIO.usos vigor_maldito > 0 e @USUARIO.contador cargas_vigor > 0 entao subtrair 1 em @USUARIO.contador cargas_vigor, somar 2d8 + @USUARIO.bonus vigor_maldito em @USUARIO.vida","explicacao":"A cura exige usos nativos disponíveis e uma carga no contador cargas_vigor da regra personalizada. Consome uma carga desse contador e cura 2d8 mais o bônus de Vigor Maldito. Não consome os usos nativos automaticamente: para usar esse exemplo, vincule também o custo nativo no construtor.","legado":"se @USUARIO.vigor_maldito_usos > 0 entao subtrair 1 em @USUARIO.vigor_maldito_usos, somar 2d8 + @USUARIO.vigor_maldito_bonus em @USUARIO.vida","aliases":"nenhum listado"},{"id":"331","origem":"visao_escuridao","modelo":"iluminacao escuridao","formula":"se @USUARIO.iluminacao escuridao > 0 entao subtrair 2 em @USUARIO.acerto","explicacao":"Quando o próprio atacante está em escuridão total, recebe -2 no Acerto por não enxergar o alvo. Em penumbra ou luz plena, esta penalidade não ativa. na_escuridao é um alias para a mesma chave.","legado":"se @USUARIO.visao_escuridao > 0 entao subtrair 2 em @USUARIO.acerto","aliases":"na_escuridao"},{"id":"332","origem":"visao_normal","modelo":"iluminacao normal","formula":"se @USUARIO.iluminacao normal > 0 entao somar 2 em @USUARIO.pericia percepcao","explicacao":"Durante uma busca em um salão plenamente iluminado, o personagem recebe +2 em Percepção para ler inscrições e detalhes pequenos. No escuro ou na penumbra, esta chave vale 0 e o bônus de luz plena não se aplica.","legado":"se @USUARIO.visao_normal > 0 entao somar 2 em @USUARIO.pericia_percepcao","aliases":"nenhum listado"},{"id":"333","origem":"visao_penumbra","modelo":"iluminacao penumbra","formula":"se @USUARIO.iluminacao penumbra > 0 entao somar 2 em @USUARIO.pericia furtividade","explicacao":"Um personagem se deslocando entre sombras recebe +2 em Furtividade quando a cena está em penumbra. Em iluminação plena, não recebe esse benefício. na_penumbra é um alias aceito para esta mesma chave.","legado":"se @USUARIO.visao_penumbra > 0 entao somar 2 em @USUARIO.pericia_furtividade","aliases":"na_penumbra"},{"id":"334","origem":"voando","modelo":"voando","formula":"se @USUARIO.voando > 0 entao somar 2 em @USUARIO.defesa","explicacao":"Enquanto está voando, a criatura recebe +2 de Defesa contra ataques de inimigos presos ao chão. Quando aterrissa, o marcador volta a 0 e o bônus deixa de valer. A chave consulta o estado de movimento, não a velocidade máxima de voo.","legado":"se @USUARIO.voando > 0 entao somar 2 em @USUARIO.defesa","aliases":"nenhum listado"},{"id":"335","origem":"vontade","modelo":"vontade","formula":"se @ALVO.vontade >= @CENA.dificuldade entao subtrair 1 em @ALVO.empolgacao","explicacao":"Uma onda de medo tem CD 15; Vontade 16 permite resistir e perde apenas 1 nível de Empolgação neste ramo, enquanto Vontade 14 pode receber a condição completa da habilidade. A chave consulta a resistência mental do alvo contra o efeito.","legado":"se @ALVO.vontade >= @CENA.dificuldade entao subtrair 1 em @ALVO.empolgacao","aliases":"nenhum listado"}] as const;
